EXTENSION_GROUPS = {
    "document": [
        "txt",
        "md",
        "pdf",
    ],
    "image": [
        "jpg",
        "png",
        "gif",
    ],
    "audio": [
        "mp3",
        "wav",
    ],
    "video": [
        "mp4",
        "avi",
        "mkv",
    ],
    "archive": [
        "zip",
        "tar",
        "rar",
    ],
    "executable": [
        "exe",
        "sh",
    ],
}

ROUTING_TABLE = {
    extension: category
    for category, extensions in EXTENSION_GROUPS.items()
    for extension in extensions
}

UNKNOWN = "unknown"


def extension_of(filename):
    name = filename.strip()
    if "." not in name:
        return ""
    return name.rsplit(".", 1)[1].lower()


def categorize(files):
    return [
        ROUTING_TABLE.get(extension_of(filename), UNKNOWN)
        for filename in files
    ]


def summarize(files):
    counts = {}
    for category in categorize(files):
        counts[category] = counts.get(category, 0) + 1
    return counts


def format_report(files):
    pairs = list(zip(files, categorize(files)))
    width = max((len(name) for name, _ in pairs), default=0)
    lines = [
        "{0:<{2}}  ->  {1}".format(name, category, width)
        for name, category in pairs
    ]
    counts = summarize(files)
    lines.append("")
    lines.extend(
        "{0}: {1}".format(category, counts[category])
        for category in sorted(counts)
    )
    return "\n".join(lines)


def main():
    sample = [
        "report.pdf",
        "song.mp3",
        "holiday.JPG",
        "backup.tar",
        "installer.exe",
        "clip.mkv",
        "notes",
        "data.csv",
    ]
    print(categorize(["report.pdf", "song.mp3"]))
    print(format_report(sample))


if __name__ == "__main__":
    main()

