    "fire": ("aries", "leo", "sagittarius"),
    "earth": ("taurus", "virgo", "capricorn"),
    "air": ("gemini", "libra", "aquarius"),
    "water": ("cancer", "scorpio", "pisces"),
}


def validate(month, day):
    if month not in DAYS_IN_MONTH:
        raise ValueError("month must be between 1 and 12, got {}".format(month))
    if not 1 <= day <= DAYS_IN_MONTH[month]:
        raise ValueError("day {} is out of range for month {}".format(day, month))


def zodiac(month, day):
    validate(month, day)
    date = (month, day)
    for sign in SIGNS:
        start, end = sign["start"], sign["end"]
        if start <= end:
