    "onion": {"protein": 1.1, "carbs": 9.3, "fat": 0.1, "grams": 70.0},
    "garlic": {"protein": 6.4, "carbs": 33.1, "fat": 0.5, "grams": 6.0}
}


def lookup(ingredient):
    key = str(ingredient).strip().lower()
    if key not in FOOD_DB:
        raise KeyError("unknown ingredient: {!r}".format(ingredient))
    return FOOD_DB[key]


def portion_macros(ingredient):
    entry = lookup(ingredient)
    share = entry["grams"] / 100.0
    return {
        "protein": entry["protein"] * share,
        "carbs": entry["carbs"] * share,
        "fat": entry["fat"] * share
    }


def macro_totals(recipe):
    if isinstance(recipe, str) or not hasattr(recipe, "__iter__"):
        raise TypeError("recipe must be a list of ingredient strings")
    totals = {
        "protein": 0.0,
        "carbs": 0.0,
        "fat": 0.0
    }
    for ingredient in recipe:
        macros = portion_macros(ingredient)
        for macro in totals:
            totals[macro] += macros[macro]
    return totals


def calories(recipe):
    totals = macro_totals(recipe)
    total = sum(totals[macro] * factor for macro, factor in MACRO_CALORIES.items())
    return round(float(total), 1)


def format_report(recipe):
    totals = macro_totals(recipe)
    lines = [
        "Recipe: " + ", ".join(str(item).strip().lower() for item in recipe),
        "  protein: {:6.1f} g".format(totals["protein"]),
        "  carbs:   {:6.1f} g".format(totals["carbs"]),
        "  fat:     {:6.1f} g".format(totals["fat"]),
        "  energy:  {:6.1f} kcal".format(calories(recipe))
    ]
    return "\n".join(lines)


def main():
    recipes = [
        ["egg", "bread", "butter"],
        ["chicken", "rice", "broccoli", "garlic"],
        ["beef", "potato", "onion"],
        ["milk", "banana", "apple"],
        ["cheese", "bread"]
    ]
    for recipe in recipes:
        print(format_report(recipe))
        print()
    richest = sorted(FOOD_DB, key=lambda name: calories([name]), reverse=True)[:3]
    print("Highest energy portions: " + ", ".join(richest))


if __name__ == "__main__":
