PENALTIES = {
    "overweight": 100,
    "oversized": 150,
}

TIER_RULES = {
    "basic": {
        "base_prices": [75, 100, 150, 200],
        "weight_limit": 20,
        "size_limit": 150,
    },
    "economy": {
        "base_prices": [50, 100, 150, 200],
        "weight_limit": 32,
        "size_limit": 158,
    },
    "business": {
        "base_prices": [0, 50, 100, 175],
        "weight_limit": 32,
        "size_limit": 165,
    },
    "first": {
        "base_prices": [0, 0, 75, 150],
        "weight_limit": 40,
        "size_limit": 180,
    },
}


def normalize_bag(bag):
    if isinstance(bag, (int, float)):
        return {"weight": float(bag), "size": 0.0}
    return {
        "weight": float(bag["weight"]),
        "size": float(bag.get("size", 0.0)),
    }


def bag_charge(position, bag, rules):
    prices = rules["base_prices"]
    base = prices[min(position, len(prices) - 1)]
    penalties = []
    if bag["weight"] > rules["weight_limit"]:
        penalties.append("overweight")
    if bag["size"] > rules["size_limit"]:
        penalties.append("oversized")
    return {
        "base": base,
        "penalties": penalties,
        "total": base + sum(PENALTIES[name] for name in penalties),
    }


def breakdown(bags, tier):
    key = tier.strip().lower()
    if key not in TIER_RULES:
        raise ValueError("unknown tier: {0}".format(tier))
    rules = TIER_RULES[key]
    return [
        bag_charge(position, normalize_bag(bag), rules)
        for position, bag in enumerate(bags)
    ]


def fee(bags, tier):
    return int(sum(charge["total"] for charge in breakdown(bags, tier)))


def report(bags, tier):
    lines = ["{0} tier, {1} bag(s)".format(tier, len(bags))]
    for number, charge in enumerate(breakdown(bags, tier), start=1):
        note = ", ".join(charge["penalties"]) or "within limits"
        lines.append(
            "  bag {0}: base {1} + penalties {2} ({3})".format(
                number,
                charge["base"],
                charge["total"] - charge["base"],
                note,
            )
        )
    lines.append("  total: {0}".format(fee(bags, tier)))
    return "\n".join(lines)


def main():
    itineraries = [
        ([25, 30], "economy"),
        ([{"weight": 24, "size": 170}], "basic"),
        ([18, 33, {"weight": 12, "size": 200}], "business"),
        ([41, 20, 20, 20, 20], "first"),
    ]
    for bags, tier in itineraries:
        print(report(bags, tier))


if __name__ == "__main__":
    main()

