from collections import Counter

RANK_VALUES = {
    "two": 2,
    "three": 3,
    "four": 4,
    "five": 5,
    "six": 6,
    "seven": 7,
    "eight": 8,
    "nine": 9,
    "ten": 10,
    "jack": 11,
    "queen": 12,
    "king": 13,
    "ace": 14,
}

SUITS = (
    "hearts",
    "diamonds",
    "clubs",
    "spades",
)

HAND_STRENGTHS = {
    "high card": 1,
    "one pair": 2,
    "two pair": 3,
    "three of a kind": 4,
    "straight": 5,
    "flush": 6,
    "full house": 7,
    "four of a kind": 8,
    "straight flush": 9,
    "royal flush": 10,
}

SHAPE_NAMES = {
    (4, 1): "four of a kind",
    (3, 2): "full house",
    (3, 1, 1): "three of a kind",
    (2, 2, 1): "two pair",
    (2, 1, 1, 1): "one pair",
}


def parse_card(card):
    parts = card.lower().split()
    if len(parts) != 2:
        raise ValueError("card must be given as '<rank> <suit>': %r" % card)
    rank, suit = parts
    if rank not in RANK_VALUES:
        raise ValueError("unknown rank: %r" % rank)
    if suit not in SUITS:
        raise ValueError("unknown suit: %r" % suit)
    return RANK_VALUES[rank], suit


def tally(cards):
    if len(cards) != 5:
        raise ValueError("a poker hand needs exactly five cards")
    parsed = [parse_card(card) for card in cards]
    if len(set(parsed)) != 5:
        raise ValueError("duplicate cards in hand")
    return {
        "ranks": Counter(rank for rank, _ in parsed),
        "suits": Counter(suit for _, suit in parsed),
    }


def straight_high(ranks):
    values = sorted(ranks)
    if len(values) != 5:
        return None
    if values == [2, 3, 4, 5, 14]:
        return 5
    if values[4] - values[0] == 4:
        return values[4]
    return None


def classify(cards):
    counts = tally(cards)
    ranks, suits = counts["ranks"], counts["suits"]
    flush = max(suits.values()) == 5
    high = straight_high(ranks)
    if flush and high == 14:
        return "royal flush"
    if flush and high is not None:
        return "straight flush"
    shape = tuple(sorted(ranks.values(), reverse=True))
    if shape in SHAPE_NAMES:
        return SHAPE_NAMES[shape]
    if flush:
        return "flush"
    if high is not None:
        return "straight"
    return "high card"


def hand(cards):
    return HAND_STRENGTHS[classify(cards)]


def report(hands):
    lines = []
    for cards in hands:
        name = classify(cards)
        lines.append("%-40s %-15s %2d" % (", ".join(cards), name, hand(cards)))
    return "\n".join(lines)


def main():
    examples = [
        ["ace hearts", "king hearts", "queen hearts", "jack hearts", "ten hearts"],
        ["nine clubs", "eight clubs", "seven clubs", "six clubs", "five clubs"],
        ["four spades", "four hearts", "four clubs", "four diamonds", "king spades"],
        ["three spades", "three hearts", "three clubs", "jack diamonds", "jack spades"],
        ["two spades", "three hearts", "four clubs", "five diamonds", "ace spades"],
        ["ten spades", "seven hearts", "four clubs", "three diamonds", "two spades"],
    ]
    print(report(examples))


if __name__ == "__main__":
    main()

