INFORMATIONAL = {
    100: "continue",
    101: "switching protocols",
}
SUCCESS = {
    200: "ok",
    201: "created",
    204: "no content",
}
REDIRECTION = {
    301: "moved permanently",
    302: "found",
    304: "not modified",
    307: "temporary redirect",
}
CLIENT_ERROR = {
    400: "bad request",
    401: "unauthorized",
    403: "forbidden",
    404: "not found",
    408: "request timeout",
    410: "gone",
    429: "too many requests",
}
SERVER_ERROR = {
    500: "internal server error",
    501: "not implemented",
    502: "bad gateway",
    503: "service unavailable",
    504: "gateway timeout",
    505: "http version not supported",
}
STATUS_TEXT = {
    **INFORMATIONAL,
    **SUCCESS,
    **REDIRECTION,
    **CLIENT_ERROR,
    **SERVER_ERROR,
}
UNKNOWN = "unknown error"
CLASS_NAMES = {
    1: "informational",
    2: "success",
    3: "redirection",
    4: "client error",
    5: "server error",
}


def status(code):
    return STATUS_TEXT.get(code, UNKNOWN)


def is_error(code):
    return code // 100 in (4, 5)


def format_status(code):
    text = status(code)
    if text == UNKNOWN:
        return "{0}: {1}".format(code, UNKNOWN)
    marker = "!" if is_error(code) else "-"
    return "{0} {1} {2} ({3})".format(marker, code, text, CLASS_NAMES[code // 100])


def main():
    sample = [
        200,
        302,
        404,
        503,
        599,
    ]
    for code in sample:
        print(format_status(code))
    print("errors in sample:", sum(1 for code in sample if is_error(code)))


if __name__ == "__main__":
    main()

