INVENTORY = {
    "water": {
        "price": 1.00,
        "stock": 5,
    },
    "cola": {
        "price": 1.50,
        "stock": 4,
    },
    "diet cola": {
        "price": 1.50,
        "stock": 3,
    },
    "iced tea": {
        "price": 1.25,
        "stock": 2,
    },
    "orange juice": {
        "price": 1.75,
        "stock": 2,
    },
    "chips": {
        "price": 1.50,
        "stock": 6,
    },
    "pretzels": {
        "price": 1.25,
        "stock": 4,
    },
    "candy bar": {
        "price": 1.10,
        "stock": 7,
    },
    "gum": {
        "price": 0.60,
        "stock": 9,
    },
    "mints": {
        "price": 0.55,
        "stock": 8,
    },
}

COINS = [
    ("dollar", 1.00),
    ("quarter", 0.25),
    ("dime", 0.10),
    ("nickel", 0.05),
]


def vend(item, payment):
    key = str(item).strip().lower()
    slot = INVENTORY.get(key)
    if slot is None:
        return ("unknown item", round(payment, 2))
    if slot["stock"] <= 0:
        return ("sold out", round(payment, 2))
    if payment < slot["price"]:
        return ("insufficient funds", round(payment, 2))
    slot["stock"] -= 1
    return ("success", round(payment - slot["price"], 2))


def make_change(amount):
    remaining = round(amount, 2)
    breakdown = {}
    for name, value in COINS:
        count, remaining = divmod(round(remaining, 2), value)
        if count:
            breakdown[name] = int(count)
    return breakdown


def format_receipt(item, payment, result):
    message, change = result
    lines = [
        "requested: {0}".format(item),
        "paid: ${0:.2f}".format(payment),
        "result: {0}".format(message),
        "change: ${0:.2f}".format(change),
    ]
    if message == "success" and change > 0:
        coins = make_change(change)
        lines.append("coins: " + ", ".join(
            "{0} x{1}".format(n, c) for n, c in coins.items()
        ))
    return "\n".join(lines)


def main():
    requests = [
        ("chips", 2.00),
        ("iced tea", 1.00),
        ("Gum", 5.00),
        ("kale", 1.00),
        ("orange juice", 2.00),
        ("orange juice", 2.00),
        ("orange juice", 2.00),
    ]
    for item, payment in requests:
        print(format_receipt(item, payment, vend(item, payment)))
        print("-" * 24)
    print("remaining stock:")
    for name in sorted(INVENTORY):
        print("  {0}: {1}".format(name, INVENTORY[name]["stock"]))


if __name__ == "__main__":
    main()

