"""Lookup utility that maps country names to their continental region."""

CONTINENT_COUNTRIES = {
    "north america": [
        "canada",
        "usa",
        "mexico",
    ],
    "south america": [
        "brazil",
        "argentina",
        "peru",
    ],
    "europe": [
        "uk",
        "france",
        "germany",
        "italy",
    ],
    "asia": [
        "china",
        "japan",
        "india",
        "thailand",
    ],
    "africa": [
        "egypt",
        "nigeria",
        "south africa",
        "kenya",
    ],
}

ALIASES = {
    "united states": "usa",
    "united states of america": "usa",
    "united kingdom": "uk",
    "great britain": "uk",
    "england": "uk",
    "deutschland": "germany",
}

COUNTRY_TO_CONTINENT = {
    country: region
    for region, countries in CONTINENT_COUNTRIES.items()
    for country in countries
}


def normalize(country):
    """Collapse whitespace and case so lookups are forgiving about formatting."""
    cleaned = " ".join(str(country).split()).lower()
    return ALIASES.get(cleaned, cleaned)


def continent(country):
    """Return the continent of `country`, or None when it is not in the database."""
    return COUNTRY_TO_CONTINENT.get(normalize(country))


def countries_in(region):
    """Return the sorted country names recorded for a continent."""
    return sorted(CONTINENT_COUNTRIES.get(normalize(region), []))


def describe(country):
    region = continent(country)
    if region is None:
        return "{}: not found in the database".format(country)
    return "{}: {}".format(country, region)


def database_summary():
    lines = []
    for region in sorted(CONTINENT_COUNTRIES):
        members = countries_in(region)
        lines.append("{} ({}): {}".format(
            region,
            len(members),
            ", ".join(members),
        ))
    return "\n".join(lines)


def main():
    queries = [
        "japan",
        "Canada",
        "  south africa ",
        "United Kingdom",
        "peru",
        "atlantis",
    ]
    for query in queries:
        print(describe(query))
    print()
    print(database_summary())


if __name__ == "__main__":
    main()

