ALERT_REGISTRY = {
    "tornado": "take cover immediately in a windowless room",
    "hurricane": "evacuate coastal areas and secure all windows",
    "blizzard": "avoid all travel and conserve indoor heat",
    "flood": "move to higher ground and avoid flooded roads",
    "thunderstorm": "stay indoors and unplug sensitive electronics",
    "heatwave": "drink water often and stay out of direct sun",
    "freeze": "protect exposed pipes and bring pets inside",
    "fog": "reduce speed and use low beam headlights",
    "hail": "shelter vehicles and stay away from skylights",
    "wind": "secure loose objects and avoid tall trees",
}

CLEAR_SKIES = "clear skies, no warnings in effect"

SEVERITY = {
    "tornado": "extreme",
    "hurricane": "extreme",
    "blizzard": "severe",
    "flood": "severe",
    "thunderstorm": "moderate",
    "heatwave": "severe",
    "freeze": "moderate",
    "fog": "minor",
    "hail": "moderate",
    "wind": "minor",
}


def normalize(condition):
    if not isinstance(condition, str):
        return ""
    return condition.strip().lower()


def alert(condition):
    return ALERT_REGISTRY.get(normalize(condition), CLEAR_SKIES)


def severity_of(condition):
    return SEVERITY.get(normalize(condition), "none")


def broadcast(condition):
    code = normalize(condition) or "unknown"
    return "[{}] {}: {}".format(
        severity_of(condition).upper(),
        code,
        alert(condition),
    )


def summarize(conditions):
    report = {}
    for condition in conditions:
        report[normalize(condition) or "unknown"] = {
            "severity": severity_of(condition),
            "message": alert(condition),
        }
    return report


def main():
    watch_list = [
        "tornado",
        "Hurricane",
        "  flood  ",
        "hail",
        "picnic weather",
        None,
    ]
    for condition in watch_list:
        print(broadcast(condition))
    print()
    extreme = sorted(
        code
        for code, entry in summarize(watch_list).items()
        if entry["severity"] == "extreme"
    )
    print("extreme events on watch:", ", ".join(extreme))


if __name__ == "__main__":
    main()

