        "mode": "train", "accessible": False,
    },
    "west zone": {
        "cost": 4.0, "distance": 14, "region": "rural",
        "mode": "bus", "accessible": True,
    },
    "airport zone": {
        "cost": 8.0, "distance": 20, "region": "outer",
        "mode": "express", "accessible": True,
    },
    "harbor zone": {
        "cost": 6.0, "distance": 8, "region": "coastal",
        "mode": "ferry", "accessible": True,
    },
    "stadium zone": {
        "cost": 5.0, "distance": 6, "region": "downtown",
        "mode": "tram", "accessible": True,
    },
}


def fare(trips):
    total_cost = 0.0
    total_distance = 0
    for name in trips:
        zone = ZONES.get(name)
        if zone is None:
            raise KeyError("unknown zone: {!r}".format(name))
        total_cost += zone["cost"]
        total_distance += zone["distance"]
    return total_cost, total_distance


def journey_details(trips):
    total_cost, total_distance = fare(trips)
    return {
        "stops": len(trips),
        "cost": total_cost,
        "distance": total_distance,
        "modes": sorted({ZONES[name]["mode"] for name in trips}),
        "regions": sorted({ZONES[name]["region"] for name in trips}),
        "step_free": all(ZONES[name]["accessible"] for name in trips),
    }


def inaccessible_stops(trips):
    return [name for name in trips if not ZONES[name]["accessible"]]


def format_summary(trips):
    details = journey_details(trips)
    lines = [
        "Route: " + " -> ".join(trips),
        "Stops: {}".format(details["stops"]),
        "Cost: ${:.2f} over {} km".format(details["cost"], details["distance"]),
        "Modes: " + ", ".join(details["modes"]),
        "Regions: " + ", ".join(details["regions"]),
    ]
    if not details["step_free"]:
        lines.append("Step-free access missing at: " + ", ".join(inaccessible_stops(trips)))
    return "\n".join(lines)


