    },
    "crux": {
        "hemisphere": "south",
        "primary_star": "acrux",
        "area": 68,
        "month": "may",
        "origin": "modern",
    },
    "cassiopeia": {
        "hemisphere": "north",
        "primary_star": "schedar",
        "area": 598,
        "month": "november",
        "origin": "greek myth",
    },
    "scorpius": {
        "hemisphere": "south",
        "primary_star": "antares",
        "area": 497,
        "month": "july",
        "origin": "greek myth",
    },
    "cygnus": {
        "hemisphere": "north",
        "primary_star": "deneb",
        "area": 804,
        "month": "september",
        "origin": "greek myth",
    },
    "centaurus": {
        "hemisphere": "south",
        "primary_star": "alpha centauri",
        "area": 1060,
        "month": "may",
        "origin": "greek myth",
    },
    "canis major": {
        "hemisphere": "south",
        "primary_star": "sirius",
        "area": 380,
        "month": "february",
        "origin": "greek myth",
    },
}


def lookup(name):
    key = " ".join(str(name).lower().split())
    if key not in ATLAS:
        raise ValueError("unknown constellation: {!r}".format(name))
    return ATLAS[key]


def locate(stars):
    total = 0
    primaries = []
    for name in stars:
        info = lookup(name)
        total += info["area"]
        primaries.append(info["primary_star"])
    return (total, primaries)


def group_by_hemisphere(stars):
    groups = {}
    for name in stars:
        groups.setdefault(lookup(name)["hemisphere"], []).append(name)
    return groups


def viewing_schedule(stars):
    pairs = [(name, lookup(name)["month"]) for name in stars]
    return sorted(pairs, key=lambda pair: MONTH_ORDER.index(pair[1]))


def format_report(stars):
    total, primaries = locate(stars)
    lines = [
        "Constellations observed: {}".format(len(stars)),
        "Total area: {} square degrees".format(total),
        "Primary stars: {}".format(", ".join(primaries)),
    ]
    for hemisphere, members in sorted(group_by_hemisphere(stars).items()):
        lines.append("  {}: {}".format(hemisphere, ", ".join(sorted(members))))
    for name, month in viewing_schedule(stars):
        lines.append("  best in {}: {} ({})".format(month, name, lookup(name)["origin"]))
    return "\n".join(lines)


def main():
    observations = [
        ["orion", "crux"],
        ["ursa major", "cassiopeia", "cygnus"],
        ["scorpius", "centaurus", "canis major"],
    ]
    print(locate(observations[0]))
    for batch in observations:
        print(format_report(batch))
        print("-" * 40)


