    "green tea": {"temperature": 80, "minutes": 3, "caffeine": "low", "origin": "china", "oxidation": "unoxidized"},
    "black tea": {"temperature": 100, "minutes": 5, "caffeine": "high", "origin": "india", "oxidation": "fully oxidized"},
    "white tea": {"temperature": 75, "minutes": 2, "caffeine": "low", "origin": "china", "oxidation": "minimally oxidized"},
    "oolong tea": {"temperature": 90, "minutes": 4, "caffeine": "medium", "origin": "taiwan", "oxidation": "partially oxidized"},
    "herbal tea": {"temperature": 100, "minutes": 7, "caffeine": "none", "origin": "global", "oxidation": "unoxidized"},
    "matcha": {"temperature": 80, "minutes": 1, "caffeine": "high", "origin": "japan", "oxidation": "unoxidized"},
    "rooibos": {"temperature": 100, "minutes": 6, "caffeine": "none", "origin": "south africa", "oxidation": "fully oxidized"},
    "pu erh": {"temperature": 95, "minutes": 5, "caffeine": "high", "origin": "china", "oxidation": "fermented"},
}

CAFFEINE_ORDER = [
    "none",
    "low",
    "medium",
    "high",
]


def lookup(tea):
    key = str(tea).strip().lower()
    if key not in TEA_PROFILES:
        raise ValueError("unknown tea: {!r} (known teas: {})".format(
            tea,
            ", ".join(sorted(TEA_PROFILES)),
        ))
    return key, TEA_PROFILES[key]


def brew(teas):
    total = 0
    origins = []
    for tea in teas:
        _, profile = lookup(tea)
        total += profile["minutes"]
        if profile["origin"] not in origins:
            origins.append(profile["origin"])
    return total, origins


def caffeine_summary(teas):
    counts = dict.fromkeys(CAFFEINE_ORDER, 0)
    for tea in teas:
        _, profile = lookup(tea)
        counts[profile["caffeine"]] += 1
    return {level: counts[level] for level in CAFFEINE_ORDER if counts[level]}


def format_report(teas):
    total, origins = brew(teas)
    lines = [
        "Tasting of {} tea(s)".format(len(teas)),
        "Total steeping time: {} minute(s)".format(total),
        "Origins: {}".format(", ".join(origins)),
    ]
    for tea in teas:
        key, profile = lookup(tea)
        lines.append("  {:<11} {:>3}C for {} min, {}, {}".format(
            key,
            profile["temperature"],
            profile["minutes"],
            profile["caffeine"] + " caffeine",
            profile["oxidation"],
        ))
    summary = caffeine_summary(teas)
    lines.append("Caffeine mix: {}".format(
        ", ".join("{} x{}".format(level, count) for level, count in summary.items()),
    ))
    return "\n".join(lines)


def main():
    tastings = [
        ["green tea", "rooibos"],
        ["matcha", "black tea", "pu erh"],
        ["white tea", "oolong tea", "herbal tea", "Green Tea"],
    ]
    for teas in tastings:
        print(format_report(teas))
        print("=> {}".format(brew(teas)))
        print()


if __name__ == "__main__":
    main()

