    "quetzalcoatl": {
        "origin": "aztec",
        "trait": "creation",
        "element": "wind",
        "alignment": "good",
        "form": "feathered serpent",
    },
}


def lookup(name):
    key = str(name).strip().lower()
    if key not in COMPENDIUM:
        raise ValueError("unknown creature: {0!r}".format(name))
    return COMPENDIUM[key]


def trace(creatures):
    elements = []
    evil = 0
    for name in creatures:
        entry = lookup(name)
        if entry["element"] not in elements:
            elements.append(entry["element"])
        if entry["alignment"] == "evil":
            evil += 1
    return elements, evil


def describe(name):
    entry = lookup(name)
    parts = [
        name.strip().lower().title(),
        "of {0} myth".format(entry["origin"]),
        "known for {0}".format(entry["trait"]),
        "a {0} bound to {1}".format(entry["form"], entry["element"]),
        "{0} aligned".format(entry["alignment"]),
    ]
    return ", ".join(parts)


def report(creatures):
    elements, evil = trace(creatures)
    lines = [describe(name) for name in creatures]
    lines.extend([
        "elements: {0}".format(", ".join(elements)),
        "evil creatures: {0}".format(evil),
    ])
    return "\n".join(lines)


def main():
    stories = [
        ["kraken", "qilin"],
        ["minotaur", "sphinx", "banshee"],
        ["kitsune", "wendigo", "quetzalcoatl", "kraken"],
    ]
    for story in stories:
        print(report(story))
        print("-" * 40)
    print(trace(["kraken", "qilin"]))


if __name__ == "__main__":
