PANTRY = {
    "butter": {
        "substitute": "applesauce", "ratio": 1.0, "flavor": "sweet",
        "allergen": "no allergens", "form": "solid",
    },
    "egg": {
        "substitute": "mashed banana", "ratio": 1.0, "flavor": "sweet",
        "allergen": "no allergens", "form": "solid",
    },
    "peanut butter": {
        "substitute": "sunflower butter", "ratio": 1.0, "flavor": "nutty",
        "allergen": "seed allergen", "form": "paste",
    },
    "wheat flour": {
        "substitute": "almond flour", "ratio": 1.0, "flavor": "nutty",
        "allergen": "nut allergen", "form": "powder",
    },
    "whole milk": {
        "substitute": "oat milk", "ratio": 1.0, "flavor": "neutral",
        "allergen": "no allergens", "form": "liquid",
    },
    "heavy cream": {
        "substitute": "coconut cream", "ratio": 1.0, "flavor": "coconut",
        "allergen": "nut allergen", "form": "liquid",
    },
    "soy sauce": {
        "substitute": "coconut aminos", "ratio": 1.0, "flavor": "salty",
        "allergen": "nut allergen", "form": "liquid",
    },
    "honey": {
        "substitute": "maple syrup", "ratio": 1.0, "flavor": "sweet",
        "allergen": "no allergens", "form": "liquid",
    },
}


def lookup(name):
    key = name.strip().lower()
    if key not in PANTRY:
        raise KeyError("no substitute known for {0!r}".format(name))
    return PANTRY[key]


def substitute(ingredients):
    total = 0.0
    warnings = []
    for name, amount in ingredients:
        entry = lookup(name)
        total += amount * entry["ratio"]
        if entry["allergen"] not in warnings:
            warnings.append(entry["allergen"])
    return total, warnings


def describe(name, amount):
    entry = lookup(name)
    volume = amount * entry["ratio"]
    return "{0} {1} -> {2:.1f} {3} ({4}, {5})".format(
        amount,
        name,
        volume,
        entry["substitute"],
        entry["flavor"],
        entry["form"],
    )


def format_report(ingredients):
    total, warnings = substitute(ingredients)
    lines = [
        "Substitution report",
        "=" * 19,
    ]
    for name, amount in ingredients:
        lines.append(describe(name, amount))
    lines.extend([
        "Total substitute volume: {0:.1f}".format(total),
        "Allergen warnings: " + ", ".join(warnings),
    ])
    return "\n".join(lines)


def main():
    orders = [
        [("butter", 2), ("wheat flour", 3)],
        [
            ("whole milk", 4),
            ("honey", 1),
            ("peanut butter", 2),
        ],
        [("heavy cream", 1), ("soy sauce", 2), ("egg", 3)],
    ]
    for order in orders:
        print(format_report(order))
        print()
    print(substitute([("butter", 2), ("wheat flour", 3)]))


if __name__ == "__main__":
    main()

