    total_km, lifts = navigate(trails)
    return {
        "trails": [name.strip().lower() for name in trails],
        "total_km": total_km,
        "lifts": lifts,
        "vertical_m": sum(TRAILS[n.strip().lower()]["vertical_m"] for n in trails),
