    },
    "downhill": {
        "front": 36, "rear": 10, "advantage": "high",
        "terrain": "slope terrain", "chain": "standard",
    },
}


def _lookup(name):
    key = str(name).strip().lower()
    if key not in GEAR_CHART:
        raise ValueError(f"unknown setup {name!r}; known setups: {', '.join(sorted(GEAR_CHART))}")
    return GEAR_CHART[key]


def gear(combinations):
    total_front = 0
    terrains = []
    for name in combinations:
        setup = _lookup(name)
        total_front += setup["front"]
        if setup["terrain"] not in terrains:
            terrains.append(setup["terrain"])
    return total_front, terrains


def summarize(combinations):
    total_front, terrains = gear(combinations)
    return {
        "total_front": total_front,
        "terrains": terrains,
        "ratios": {n: round(_lookup(n)["front"] / _lookup(n)["rear"], 2) for n in combinations},
        "chains": sorted({_lookup(n)["chain"] for n in combinations}),
    }


def describe(name):
    setup = _lookup(name)
    return (f"{name}: {setup['front']}x{setup['rear']}, {setup['advantage']} advantage, "
            f"{setup['terrain']}, {setup['chain']} chain")


def format_report(combinations):
    data = summarize(combinations)
    lines = [
        f"total front teeth: {data['total_front']}",
        f"terrain types: {', '.join(data['terrains'])}",
        f"chain lengths: {', '.join(data['chains'])}",
    ]
    for name, ratio in data["ratios"].items():
        lines.append(f"  {describe(name)} (ratio {ratio})")
    return "\n".join(lines)


def main():
    garages = [
        ["climbing", "bmx"],
        ["sprinting", "track setup", "downhill"],
        ["touring", "gravel", "cruising", "touring"],
    ]
    for garage in garages:
        print(format_report(garage))
        print("gear() ->", gear(garage))
        print()


if __name__ == "__main__":
    main()

