from collections import Counter

RECIPES = {
    "sponge cake": [
        "pastry flour",
        "caster sugar",
        "whole eggs",
        "vanilla extract",
        "baking powder",
    ],
    "pound cake": [
        "unsalted butter",
        "granulated sugar",
        "all purpose flour",
        "large eggs",
        "milk",
    ],
    "chiffon cake": [
        "vegetable oil",
        "superfine sugar",
        "cake flour",
        "separated eggs",
        "cream of tartar",
        "water",
    ],
}


def normalize_cake_name(name):
    key = " ".join(str(name).strip().lower().split())
    if key not in RECIPES:
        raise ValueError(
            "unknown cake {!r}; available: {}".format(key, ", ".join(sorted(RECIPES)))
        )
    return key


def gather_ingredients(cakes):
    master = []
    for cake in cakes:
        master.extend(RECIPES[normalize_cake_name(cake)])
    return len(cakes), sorted(set(master))


def shared_ingredients(cakes):
    usage = Counter()
    for cake in cakes:
        usage.update(set(RECIPES[normalize_cake_name(cake)]))
    return sorted(name for name, seen in usage.items() if seen > 1)


def format_report(cakes):
    count, ingredients = gather_ingredients(cakes)
    lines = [
        "Order of {} cake(s): {}".format(count, ", ".join(cakes)),
        "Distinct ingredients needed: {}".format(len(ingredients)),
    ]
    for item in ingredients:
        lines.append("  - {}".format(item))
    overlap = shared_ingredients(cakes)
    if overlap:
        lines.append("Shared across recipes: {}".format(", ".join(overlap)))
    return "\n".join(lines)


def main():
    orders = [
        [
            "Sponge Cake",
            "pound cake",
        ],
        [
            "chiffon cake",
        ],
        [
            "pound cake",
            "chiffon cake",
            "sponge cake",
        ],
    ]
    for order in orders:
        print(format_report(order))
        print()
    print(gather_ingredients(["sponge cake", "pound cake"]))


if __name__ == "__main__":
