PLANET_CATALOG = {
    "mercury": ("solid cores", "thin atmospheres"),
    "venus": ("solid cores", "thin atmospheres"),
    "earth": ("solid cores", "thin atmospheres"),
    "mars": ("solid cores", "thin atmospheres"),
    "jupiter": ("dense cores", "hydrogen atmospheres"),
    "saturn": ("dense cores", "hydrogen atmospheres"),
    "uranus": ("rocky cores", "methane atmospheres"),
    "neptune": ("rocky cores", "methane atmospheres"),
}

OBSERVATION_STATUSES = [
    "active",
    "pending",
    "completed",
    "delayed",
    "archived",
]

CATEGORY_BY_CORE = {
    "solid cores": "terrestrial",
    "dense cores": "gas giant",
    "rocky cores": "ice giant",
}


def normalize(name):
    return str(name).strip().lower()


def classify_planets(planets):
    active_status = OBSERVATION_STATUSES[0]
    catalogued = []
    for planet in planets:
        key = normalize(planet)
        if key not in PLANET_CATALOG:
            raise KeyError("unknown planet: {!r}".format(planet))
        core, atmosphere = PLANET_CATALOG[key]
        catalogued.append((
            key,
            core,
            atmosphere,
            active_status,
        ))
    return catalogued


def group_by_category(records):
    grouped = {}
    for name, core, _atmosphere, _status in records:
        grouped.setdefault(CATEGORY_BY_CORE[core], []).append(name)
    return grouped


def format_report(records):
    lines = [
        "{:<9} {:<13} {:<21} {}".format("PLANET", "CORE", "ATMOSPHERE", "STATUS"),
    ]
    for name, core, atmosphere, status in records:
        lines.append("{:<9} {:<13} {:<21} {}".format(name, core, atmosphere, status))
    grouped = group_by_category(records)
    for category in sorted(grouped):
        lines.append("{}: {}".format(category, ", ".join(sorted(grouped[category]))))
    return "\n".join(lines)


def main():
    survey = [
        "Earth",
        "mars",
        " jupiter",
        "neptune",
        "saturn",
    ]
    records = classify_planets(survey)
    print(format_report(records))
    print()
    print(classify_planets(["earth"]))


if __name__ == "__main__":
    main()

