SHOP_PRIORITIES = [
    "safety critical",
    "performance related",
    "cosmetic",
    "optional"
]


def normalize_system(name):
    cleaned = name.strip().lower()
    for suffix in ("system", "systems"):
        if cleaned.endswith(suffix):
            cleaned = cleaned[: -len(suffix)].strip()
    return cleaned


def validate_systems(system_names):
    known = []
    unknown = []
    for name in system_names:
        key = normalize_system(name)
        if key in MAINTENANCE_TASKS:
            known.append(key)
        else:
            unknown.append(name)
    if unknown:
        raise ValueError("unknown systems: " + ", ".join(unknown))
    return known


def assign_priorities(systems):
    return {system: SHOP_PRIORITIES[0] for system in systems}


def gather_tasks(system_names):
    systems = validate_systems(system_names)
    tasks = []
    for system in systems:
        tasks.extend(MAINTENANCE_TASKS[system])
    return len(tasks), tasks


def format_work_order(system_names):
    count, tasks = gather_tasks(system_names)
    priorities = assign_priorities(validate_systems(system_names))
