    ],
}

DEFAULT_TEMPERATURE_C = 94
DEFAULT_GRIND_SIZE = "medium-fine"


def normalize_roast(name):
    cleaned = name.strip().lower()
    for suffix in (
        " roasts",
        " roast",
    ):
        if cleaned.endswith(suffix):
            cleaned = cleaned[: -len(suffix)]
    return cleaned


def build_brew_profiles(roast_levels,
                        temperature=DEFAULT_TEMPERATURE_C,
                        grind_size=DEFAULT_GRIND_SIZE):
    profiles = []
    for requested in roast_levels:
        key = normalize_roast(requested)
        if key not in ROAST_FLAVOR_NOTES:
            raise KeyError("unknown roast level: {!r}".format(requested))
        profiles.append((
            key,
            list(ROAST_FLAVOR_NOTES[key]),
            temperature,
            grind_size,
        ))
    return profiles


def format_profile(profile):
    roast, flavors, temperature, grind_size = profile
    return "{} roast | {} | {}C | {} grind".format(
        roast,
        ", ".join(flavors),
        temperature,
        grind_size,
    )


def build_report(roast_levels):
    return "\n".join(
        format_profile(profile)
        for profile in build_brew_profiles(roast_levels)
    )


