MARGHERITA = [
    "fresh mozzarella",
    "san marzano tomatoes",
    "fresh basil",
    "extra virgin olive oil",
    "sea salt",
]

SUPREME = [
    "pepperoni",
    "italian sausage",
    "green bell peppers",
    "red onions",
    "black olives",
    "mushrooms",
]

HAWAIIAN = [
    "ham",
    "pineapple chunks",
    "bacon bits",
    "mozzarella",
    "tomato sauce",
]

RECIPES = {
    "margherita": MARGHERITA,
    "supreme": SUPREME,
    "hawaiian": HAWAIIAN,
}


def normalize_pie_name(pie):
    return str(pie).strip().lower()


def aggregate_order(pies):
    unique_ingredients = set()
    count = 0
    unknown = []
    for pie in pies:
        name = normalize_pie_name(pie)
        if name in RECIPES:
            unique_ingredients.update(RECIPES[name])
            count += 1
        else:
            unknown.append(name)
    if unknown:
        raise ValueError("unknown pie(s): " + ", ".join(sorted(unknown)))
    return count, sorted(unique_ingredients)


def format_order(pies):
    count, ingredients = aggregate_order(pies)
    lines = [
        "Pies ordered: {}".format(count),
        "Distinct ingredients: {}".format(len(ingredients)),
    ]
    lines.extend("  - " + item for item in ingredients)
    return "\n".join(lines)


def main():
    orders = [
        ["margherita"],
        ["hawaiian", "Margherita"],
        ["supreme", "supreme", "hawaiian"],
    ]
    for order in orders:
        print("Order: " + ", ".join(order))
        print(format_order(order))
        print()
    print(aggregate_order(["margherita"]))


if __name__ == "__main__":
    main()

