AREA_LIFTS = {
    "beginner area": [
        "magic carpet",
        "bunny slope tow rope",
        "discovery chair",
        "pioneer lift",
    ],
    "summit area": [
        "peak gondola",
        "high alpine quad",
        "ridge express",
        "bowl tram",
    ],
    "terrain park": [
        "freestyle chair",
        "halfpipe surface lift",
        "jumper express",
        "rail tow",
    ],
}

STANDARD_PRICE = 89.00
STANDARD_TIME = "09:00-16:00"


def normalize_area(area):
    """Return the canonical key for a loosely written area name."""
    cleaned = " ".join(str(area).strip().lower().split())
    aliases = {
        "beginner": "beginner area",
        "bunny hill": "beginner area",
        "summit": "summit area",
        "park": "terrain park",
    }
    return aliases.get(cleaned, cleaned)


def get_area_lifts(areas):
    """Pair each requested area with its lifts, the price and the operating time."""
    report = []
    for area in areas:
        key = normalize_area(area)
        if key not in AREA_LIFTS:
            raise KeyError("unknown mountain area: {!r}".format(area))
        report.append((
            key,
            list(AREA_LIFTS[key]),
            STANDARD_PRICE,
            STANDARD_TIME,
        ))
    return report


def format_entry(entry):
    """Render one (area, lifts, price, time) tuple as a single readable line."""
    area, lifts, price, time = entry
    return "{}: {} | ${:.2f} | {}".format(
        area.title(),
        ", ".join(lifts),
        price,
        time,
    )


def main():
    print(get_area_lifts(["beginner area"]))
    requested = [
        "summit",
        "terrain park",
        "Beginner Area",
    ]
    for entry in get_area_lifts(requested):
        print(format_entry(entry))
    try:
        get_area_lifts(["glacier bowl"])
    except KeyError as exc:
        print("error:", exc.args[0])


if __name__ == "__main__":
