FLYWAYS = {
    "atlantic": [
        "snow geese",
        "mallards",
        "great blue herons",
        "osprey",
        "peregrine falcons",
    ],
    "mississippi": [
        "canada geese",
        "wood ducks",
        "bald eagles",
        "sandhill cranes",
        "pelicans",
    ],
    "pacific": [
        "northern shovelers",
        "cackling geese",
        "western sandpipers",
        "arctic terns",
        "surf scoters",
    ],
}


def normalize_flyway(name):
    key = name.strip().lower()
    for suffix in (
        " flyway",
        " route",
    ):
        if key.endswith(suffix):
            key = key[: -len(suffix)]
    return key.strip()


def observed_species(flyway_names):
    species = set()
    unknown = []
    for name in flyway_names:
        key = normalize_flyway(name)
        if key in FLYWAYS:
            species.update(FLYWAYS[key])
        else:
            unknown.append(name)
    if unknown:
        raise KeyError("unknown flyway(s): " + ", ".join(unknown))
    return len(species), sorted(species)


def format_report(flyway_names, count, species):
    header = "Flyways: {} -> {} species".format(
        ", ".join(normalize_flyway(n) for n in flyway_names),
        count,
    )
    lines = [header]
    lines.extend("  - " + bird for bird in species)
    return "\n".join(lines)


def main():
    requests = [
        ["Atlantic Flyway"],
        ["mississippi", "pacific"],
        [
            "atlantic",
            "mississippi",
            "pacific",
        ],
    ]
    for names in requests:
        count, species = observed_species(names)
        print(format_report(names, count, species))
        print()
    try:
        observed_species(["central"])
    except KeyError as err:
        print("error:", err.args[0])


