    "string": {
        "seating": "front arc, left to right",
        "tuning": "A440",
    },
    "woodwind": {
        "seating": "center, behind the strings",
        "tuning": "A442",
    },
    "brass": {
        "seating": "rear, right of center",
        "tuning": "B-flat",
    },
}


def build_instrument_index(section_instruments):
    return {
        instrument: section
        for section, instruments in section_instruments.items()
        for instrument in instruments
    }


INSTRUMENT_SECTIONS = build_instrument_index(SECTION_INSTRUMENTS)


def normalize(name):
    return " ".join(str(name).strip().lower().split())


def describe_instruments(instruments):
    described = []
    for raw in instruments:
        instrument = normalize(raw)
        section = INSTRUMENT_SECTIONS.get(instrument)
        if section is None:
            raise KeyError("unknown instrument: %s" % raw)
        details = SECTION_DETAILS[section]
        described.append((
            instrument,
            section,
            details["seating"],
            details["tuning"],
        ))
    return described


def format_row(entry):
    instrument, section, seating, tuning = entry
    return "{0:<14} {1:<9} {2:<28} {3}".format(
        instrument,
        section,
        seating,
        tuning,
    )


