ZONE_STATIONS = {
    "downtown": [
        "central station",
        "union square",
        "financial district",
        "arts center",
        "government plaza",
    ],
    "urban": [
        "university",
        "medical center",
        "sports arena",
        "historic district",
        "tech park",
    ],
    "suburban": [
        "shopping mall",
        "residential park",
        "community college",
        "lakefront",
        "fairgrounds",
    ],
}

ZONE_FARES = {
    "downtown": 2.50,
    "urban": 3.25,
    "suburban": 4.00,
}


def build_station_index():
    return {
        station: zone
        for zone, stations in ZONE_STATIONS.items()
        for station in stations
    }


STATION_ZONES = build_station_index()


def normalize(name):
    return " ".join(name.strip().lower().split())


def find_zone(station):
    return STATION_ZONES.get(normalize(station))


def summarize_trip(stations):
    zones = []
    for station in stations:
        zone = find_zone(station)
        if zone is None:
            raise ValueError("unknown station: %s" % station)
        if zone not in zones:
            zones.append(zone)
    return (len(stations), zones)


def format_report(stations):
    count, zones = summarize_trip(stations)
    total_fare = sum(ZONE_FARES[zone] for zone in zones)
    lines = [
        "Stations visited: %d" % count,
        "Zones visited: %s" % ", ".join(zones),
        "Estimated fare: $%.2f" % total_fare,
    ]
    return "\n".join(lines)


def main():
    itineraries = [
        ["central station", "university"],
        ["Union Square", "arts center", "Government Plaza"],
        ["tech park", "lakefront", "fairgrounds", "medical center"],
        ["shopping mall"],
    ]
    for itinerary in itineraries:
        print(format_report(itinerary))
        print("-" * 32)
    print(summarize_trip(["central station", "university"]))


if __name__ == "__main__":
    main()

