SAND_PROPERTIES = {
    "coarse": {
        "drainage": 10,
        "retention": "low",
        "retention_points": 2,
    },
    "medium": {
        "drainage": 5,
        "retention": "moderate",
        "retention_points": 5,
    },
    "fine": {
        "drainage": 2,
        "retention": "high",
        "retention_points": 9,
    },
}

SILT_PROPERTIES = {
    "sticky": {
        "structure": 3,
    },
    "smooth": {
        "structure": 4,
    },
    "gritty": {
        "structure": 5,
    },
}

CLAY_BEHAVIORS = {
    "expansive": {
        "stability": -10,
    },
    "non expansive": {
        "stability": 5,
    },
}

IDEAL_MIXTURES = [
    {
        "name": "pure loam",
        "sand": "medium",
        "silt": "smooth",
        "clay": "non expansive",
    },
    {
        "name": "sandy loam",
        "sand": "coarse",
        "silt": "gritty",
        "clay": "non expansive",
    },
    {
        "name": "silty clay",
        "sand": "fine",
        "silt": "sticky",
        "clay": "expansive",
    },
]

COMPONENTS = (
    "sand",
    "silt",
    "clay",
)


def lookup(table, key, group):
    if key not in table:
        raise ValueError("unknown {} descriptor: {!r}".format(group, key))
    return table[key]


def parse_sample(sample):
    descriptors = sample.split(",") if isinstance(sample, str) else list(sample)
    parts = {}
    for descriptor in descriptors:
        words = descriptor.strip().lower().split()
        parts[words[-1]] = " ".join(words[:-1])
    for component in COMPONENTS:
        if component not in parts:
            raise ValueError("sample is missing a {} descriptor".format(component))
    return parts


def score_sample(parts):
    sand = lookup(SAND_PROPERTIES, parts["sand"], "sand")
    silt = lookup(SILT_PROPERTIES, parts["silt"], "silt")
    clay = lookup(CLAY_BEHAVIORS, parts["clay"], "clay")
    return {
        "drainage": sand["drainage"],
        "retention": sand["retention_points"],
        "retention_label": sand["retention"],
        "structure": silt["structure"],
        "stability": clay["stability"],
        "total": sand["drainage"] + sand["retention_points"] + silt["structure"] + clay["stability"],
    }


def closest_mixture(parts):
    def matches(mixture):
        return sum(1 for component in COMPONENTS if mixture[component] == parts[component])

    best = max(IDEAL_MIXTURES, key=matches)
    return best, matches(best)


def describe(parts, scores, mixture, shared):
    pieces = [
        "{sand} sand, {silt} silt and {clay} clay".format(**parts),
        "total {} points".format(scores["total"]),
        "({drainage} drainage, {retention} retention, {structure} structure,"
        " {stability} stability)".format(**scores),
        "with {} water retention,".format(scores["retention_label"]),
        "closest to {} ({} of 3 ideal traits).".format(mixture["name"], shared),
    ]
    return " ".join(pieces)


def classify(percentages):
    samples = percentages
    if all(isinstance(item, str) for item in percentages):
        samples = [percentages]
    sentences = []
    for sample in samples:
        parts = parse_sample(sample)
        scores = score_sample(parts)
        mixture, shared = closest_mixture(parts)
        sentences.append(describe(parts, scores, mixture, shared))
    return sentences


def main():
    example = [
        "coarse sand",
        "smooth silt",
        "expansive clay",
    ]
    batch = [
        example,
        ["medium sand", "smooth silt", "non expansive clay"],
        "fine sand, sticky silt, expansive clay",
    ]
    for sentence in classify(example):
        print(sentence)
    print("---")
    for sentence in classify(batch):
        print(sentence)


if __name__ == "__main__":
    main()

