        "efficiency": "high",
        "maintenance": "high",
    },
    "asynchronous": {
        "efficiency": "moderate",
        "maintenance": "low",
    },
}

TOWER_ADJUSTMENTS = {
    "short": -0.10,
    "medium": 0.0,
    "tall": 0.20,
}

RESTRICTED_WEATHER = [
    "hurricane",
    "tornado",
    "extreme icing",
]


def validate(conditions):
    unknown = []
    for key, table in (
        ("blade", BLADE_SPECS),
        ("generator", GENERATOR_SPECS),
        ("tower", TOWER_ADJUSTMENTS),
    ):
        value = conditions.get(key)
        if value not in table:
            unknown.append("%s=%r" % (key, value))
    if unknown:
        raise ValueError("unsupported selection: " + ", ".join(unknown))


def estimate(conditions):
