        "length_mm": 2.0,
        "needle": "fine",
    },
    "light": {
        "length_mm": 2.5,
        "needle": "universal",
    },
    "heavy": {
        "length_mm": 4.0,
        "needle": "denim",
    },
}

STRETCH_STITCHES = {
    "none": "straight stitch",
    "two way": "narrow zigzag",
    "four way": "overlock stitch",
}

THREAD_NOTES = {
    "cotton": "low durability",
    "polyester": "high durability",
    "silk": "glossy finish",
}

DELICATE_MATERIALS = [
    "chiffon",
    "organza",
    "lace",
]


def validate(fabric):
    problems = []
    if fabric.get("weight") not in WEIGHT_SETTINGS:
        problems.append("unknown weight {!r}".format(fabric.get("weight")))
    if fabric.get("stretch") not in STRETCH_STITCHES:
        problems.append("unknown stretch {!r}".format(fabric.get("stretch")))
    if fabric.get("thread") not in THREAD_NOTES:
        problems.append("unknown thread {!r}".format(fabric.get("thread")))
    return problems


def settings_for(fabric):
    problems = validate(fabric)
    if problems:
        raise ValueError("; ".join(problems))
    weight = WEIGHT_SETTINGS[fabric["weight"]]
    return {
        "length_mm": weight["length_mm"],
        "needle": weight["needle"],
        "stitch": STRETCH_STITCHES[fabric["stretch"]],
        "thread_note": THREAD_NOTES[fabric["thread"]],
        "handle_with_care": fabric.get("material") in DELICATE_MATERIALS,
    }


def stitch(fabrics):
    return [settings_for(fabric) for fabric in fabrics]


def describe(fabric, setting):
    parts = [
        "{} millimeter length".format(setting["length_mm"]),
        "{} needle".format(setting["needle"]),
        setting["stitch"],
