        },
        {
            "core_type": "multi mode step",
            "light_source": "fabry perot laser",
            "jacket": "aqua",
        },
    ]
    for number, spec in enumerate(route(layout), start=1):
        print("link %d: %s" % (number, format_spec(spec)))


