}

ADVANCED_TECHNIQUES = [
    "water bomb base",
    "squash fold",
    "petal fold",
]

LEVEL_POINTS = {
    "low": 1,
    "moderate": 2,
    "high": 3,
}


def _lookup(table, key, kind):
    if key not in table:
        raise ValueError("unknown {}: {!r}".format(kind, key))
    return table[key]


def characteristics(design):
    wing = _lookup(WING_SHAPES, design["wing"], "wing shape")
    nose = _lookup(NOSE_FOLDS, design["nose"], "nose fold")
    traits = [
        "{} speed".format(wing["speed"]),
        "{} glide".format(wing["glide"]),
        "{} drag".format(nose["drag"]),
        "{} damage risk".format(nose["damage_risk"]),
    ]
    if nose["balance"] != "neutral":
        traits.append("center of gravity {}".format(nose["balance"]))
    for name in design.get("tail", []):
        traits.append(_lookup(TAIL_MODS, name, "tail modification")["effect"])
    return traits


def score(design):
    wing = _lookup(WING_SHAPES, design["wing"], "wing shape")
    total = LEVEL_POINTS[wing["speed"]] + LEVEL_POINTS[wing["glide"]]
    if _lookup(NOSE_FOLDS, design["nose"], "nose fold")["drag"] == "reduced":
        total += 2
    for name in design.get("tail", []):
        total += TAIL_MODS[name]["points"]
    for technique in design.get("techniques", []):
        if technique in ADVANCED_TECHNIQUES:
            total += 1
    return total


def _sentence(items):
    if len(items) == 1:
        return items[0]
    return ", ".join(items[:-1]) + ", and " + items[-1]


def grade(designs):
    return [
        {
            "name": design["name"],
