        "feel": "smooth",
        "noise": "quiet",
        "bump": False,
    },
    "tactile": {
        "feel": "bump",
        "noise": "moderate",
        "bump": True,
    },
    "clicky": {
        "feel": "bump",
        "noise": "loud",
        "bump": True,
    },
}

SPRING_WEIGHTS = {
    "light": "forty grams of force",
    "medium": "fifty grams of force",
    "heavy": "sixty five grams of force",
}

HOUSING_MATERIALS = {
    "polycarbonate": "a high pitch",
    "nylon": "a deep pitch",
    "polyoxymethylene": "a muted pitch",
}

LUBRICATION_POINTS = [
    "the stem rails",
    "the spring ends",
    "the stabilizing wire",
]


def validate(preferences):
    problems = []
    for key, table in (
        ("switch", SWITCH_BEHAVIORS),
        ("spring", SPRING_WEIGHTS),
        ("housing", HOUSING_MATERIALS),
    ):
        choice = preferences.get(key)
        if choice not in table:
            problems.append("unknown {0}: {1!r}".format(key, choice))
    if problems:
        raise ValueError("; ".join(problems))


def describe_feel(switch):
    behavior = SWITCH_BEHAVIORS[switch]
    if behavior["bump"]:
        return "a bump and {0} noise".format(behavior["noise"])
    return "{0} and {1}".format(behavior["feel"], behavior["noise"])


def match(preferences):
    validate(preferences)
    return {
        "typing_feel": describe_feel(preferences["switch"]),
        "spring_force": SPRING_WEIGHTS[preferences["spring"]],
        "sound_profile": HOUSING_MATERIALS[preferences["housing"]],
        "lubrication_points": list(LUBRICATION_POINTS),
    }


def report(recommendation):
    summary = ", and ".join([
        ", ".join([
            recommendation["typing_feel"],
            recommendation["spring_force"],
        ]),
        recommendation["sound_profile"],
    ])
    points = ", ".join(recommendation["lubrication_points"])
    return "{0}\nLubricate {1}.".format(summary, points)


def main():
    recommendation = match({
        "switch": "linear",
        "spring": "heavy",
        "housing": "nylon",
    })
    print(report(recommendation))


if __name__ == "__main__":
    main()

