BRIDGE_TYPES = {
    "suspension": "supports very long spans and sways",
    "beam": "supports short spans and remains rigid",
    "arch": "supports medium spans and transfers weight outwards",
}

MATERIAL_STRENGTHS = {
    "reinforced concrete": "handles high compression",
    "structural steel": "handles high tension",
    "treated timber": "handles light local traffic",
}

FOUNDATION_TYPES = {
    "shallow footings": "suited for bedrock",
    "driven piles": "suited for soft soil",
    "drilled shafts": "suited for deep stability",
}

DYNAMIC_LOADS = [
    "heavy wind gusts",
    "traffic jams",
    "seismic tremors",
]


def normalize(span):
    return {
        "type": span["type"].strip().lower(),
        "material": span["material"].strip().lower(),
        "foundation": span["foundation"].strip().lower(),
    }


def validate(span):
    problems = []
    if span["type"] not in BRIDGE_TYPES:
        problems.append("unknown bridge type %r" % span["type"])
    if span["material"] not in MATERIAL_STRENGTHS:
        problems.append("unknown material %r" % span["material"])
    if span["foundation"] not in FOUNDATION_TYPES:
        problems.append("unknown foundation %r" % span["foundation"])
    return problems


def describe(span):
    return ", and ".join([
        ", ".join([
            BRIDGE_TYPES[span["type"]],
            MATERIAL_STRENGTHS[span["material"]],
        ]),
        FOUNDATION_TYPES[span["foundation"]],
    ])


def assess(span):
    clean = normalize(span)
    problems = validate(clean)
    if problems:
        raise ValueError("; ".join(problems))
    return {
        "design": "{type} bridge made of {material} on {foundation}".format(**clean),
        "assessment": describe(clean),
        "dynamic_loads": list(DYNAMIC_LOADS),
    }


def calculate(spans):
    return [assess(span) for span in spans]


def report(results):
    lines = []
    for result in results:
        lines.append("%s: %s" % (result["design"], result["assessment"]))
        lines.append("  checked against: %s" % ", ".join(result["dynamic_loads"]))
    return "\n".join(lines)


def main():
    proposals = [
        {
            "type": "Arch",
            "material": "Reinforced Concrete",
            "foundation": "Driven Piles",
        },
        {
            "type": "suspension",
            "material": "structural steel",
            "foundation": "drilled shafts",
        },
        {
            "type": "beam",
