SEDIMENT_FILTERS = {
    "pleated filter": {
        "action": "traps large particles",
        "maintenance": "washable",
    },
    "spun filter": {
        "action": "traps medium particles",
        "maintenance": "disposable",
    },
    "string wound filter": {
        "action": "traps fine particles",
        "maintenance": "handles high pressure",
    },
}

CARBON_STAGES = {
    "granular carbon": "removes odors",
    "carbon block": "removes chlorine",
    "catalytic carbon": "removes chloramines",
}

ADVANCED_PURIFIERS = {
    "reverse osmosis": "removes heavy metals",
    "ultraviolet light": "neutralizes bacteria",
    "ultrafiltration": "removes cysts",
}

DISSOLVED_SOLIDS = [
    "calcium",
    "magnesium",
    "sodium",
]


def lookup(component):
    key = component.strip().lower()
    if key in SEDIMENT_FILTERS:
        return SEDIMENT_FILTERS[key]["action"]
    if key in CARBON_STAGES:
        return CARBON_STAGES[key]
    if key in ADVANCED_PURIFIERS:
        return ADVANCED_PURIFIERS[key]
    raise KeyError("unknown filtration component: " + component)


def describe(actions):
    if len(actions) == 1:
        return actions[0]
    return ", ".join(actions[:-1]) + ", and " + actions[-1]


