ROPE_CATEGORIES = {
    "single": "used alone and is thick",
    "half": "used in pairs to reduce drag",
    "twin": "clipped together for maximum security",
}

CORE_TREATMENTS = {
    "untreated": "absorbs water quickly",
    "dry": "resists water and dirt",
    "ultra dry": "prevents freezing in alpine conditions",
}

ELONGATION_TYPES = {
    "static": "for hauling",
    "low stretch": "for caving",
    "dynamic": "absorbs falling impacts",
}

HIGH_RISK_SCENARIOS = [
    "sharp edges",
    "rock fall",
    "crevasse rescue",
]


def normalise(route):
    return {
        "name": str(route.get("name", "unnamed route")).strip(),
        "category": str(route.get("category", "")).strip().lower(),
        "treatment": str(route.get("treatment", "")).strip().lower(),
        "elongation": str(route.get("elongation", "")).strip().lower(),
        "hazards": [str(h).strip().lower() for h in route.get("hazards", [])],
    }


def validate(route):
    problems = []
    for field, table in (
        ("category", ROPE_CATEGORIES),
        ("treatment", CORE_TREATMENTS),
        ("elongation", ELONGATION_TYPES),
    ):
        if route[field] not in table:
            problems.append("unknown {}: {!r}".format(field, route[field]))
    return problems


def recommend(route):
    hazards = [h for h in route["hazards"] if h in HIGH_RISK_SCENARIOS]
    return {
        "name": route["name"],
        "traits": [
            ROPE_CATEGORIES[route["category"]],
            CORE_TREATMENTS[route["treatment"]],
            ELONGATION_TYPES[route["elongation"]],
        ],
        "hazards": hazards,
        "double_up": bool(hazards) and route["category"] != "single",
    }


def select(routes):
    results = []
    for raw in routes:
        route = normalise(raw)
        problems = validate(route)
        if problems:
            results.append({"name": route["name"], "errors": problems})
        else:
            results.append(recommend(route))
    return results


def format_report(recommendations):
    lines = []
    for item in recommendations:
        if "errors" in item:
            lines.append("{}: rejected ({})".format(item["name"], "; ".join(item["errors"])))
            continue
        lines.append("{}: {}".format(item["name"], ", ".join(item["traits"])))
        if item["hazards"]:
            lines.append("  high risk: " + ", ".join(item["hazards"]))
        if item["double_up"]:
            lines.append("  clip both strands for redundancy")
    return "\n".join(lines)


def main():
    expedition = [
        {
            "name": "Sunny Crag",
            "category": "single",
            "treatment": "dry",
            "elongation": "dynamic",
        },
        {
            "name": "North Face Traverse",
            "category": "twin",
            "treatment": "ultra dry",
            "elongation": "dynamic",
            "hazards": ["sharp edges", "crevasse rescue", "midges"],
        },
        {
            "name": "Deep Pot Descent",
            "category": "half",
            "treatment": "untreated",
            "elongation": "bungee",
        },
    ]
    print(format_report(select(expedition)))


if __name__ == "__main__":
    main()

