STANDARD_PORTS = {
    "secure shell": 22,
    "hyper text transfer": 80,
    "secure hyper text transfer": 443,
    "file transfer": 21,
    "domain name service": 53,
    "simple mail transfer": 25,
    "post office protocol": 110,
    "internet message access": 143,
}

TRANSPORT_TYPES = {
    "transmission control": [
        "secure shell",
        "hyper text transfer",
        "secure hyper text transfer",
        "file transfer",
        "simple mail transfer",
        "post office protocol",
        "internet message access",
    ],
    "user datagram": [
        "domain name service",
    ],
}


def transport_of(protocol):
    for transport, protocols in TRANSPORT_TYPES.items():
        if protocol in protocols:
            return transport
    return "unknown"


def audit(traffic):
    report = []
    for protocol, port in traffic:
        report.append([
            protocol,
            transport_of(protocol),
            STANDARD_PORTS.get(protocol) == port,
        ])
    return report


def summarize(rows):
    totals = {
        "standard": 0,
        "nonstandard": 0,
    }
    for row in rows:
        if row[2]:
            totals["standard"] += 1
        else:
            totals["nonstandard"] += 1
    return totals


def format_row(row):
    protocol, transport, is_standard = row
    return "{:<27}{:<22}{}".format(
        protocol,
        transport,
        "standard" if is_standard else "non-standard",
    )


def main():
