        ("secure shell", 22),
        ("hyper text transfer", 8080),
        ("secure hyper text transfer", 443),
        ("domain name service", 53),
        ("simple mail transfer", 25),
        ("internet message access", 143),
        ("post office protocol", 995),
    ]
    rows = audit(traffic)
    for row in rows:
        print(format_row(row))
    totals = summarize(rows)
    print("standard: {standard}, non-standard: {nonstandard}".format(
        standard=totals["standard"],
        nonstandard=totals["nonstandard"],
    ))


if __name__ == "__main__":
