FILM_PROCESSES = {
    "color negative": ("c41", 195),
    "black and white classic": ("d76", 480),
    "color reversal": ("e6", 360),
    "black and white tabular": ("tmax", 420),
    "instant color": ("monobath", 300),
    "infrared": ("hc110", 600),
    "motion picture": ("ecn2", 180),
    "orthochromatic": ("rodinal", 720),
}


def normalize(film):
    """Reduce a user supplied film name to the canonical lookup key."""
    return " ".join(str(film).strip().lower().replace("-", " ").split())


def develop(rolls):
    """Map each film type to its (process, seconds) pair."""
    schedule = []
    for roll in rolls:
        key = normalize(roll)
        if key not in FILM_PROCESSES:
            raise ValueError("unknown film type: {!r}".format(roll))
        schedule.append(FILM_PROCESSES[key])
    return schedule


def format_duration(seconds):
    minutes, rest = divmod(seconds, 60)
    return "{}:{:02d}".format(minutes, rest)


def summarize(rolls):
    """Group the developed rolls by process, counting rolls and total time."""
    totals = {}
    for process, seconds in develop(rolls):
        count, total = totals.get(process, (0, 0))
        totals[process] = (
            count + 1,
            total + seconds,
        )
    return totals


def report(rolls):
    lines = [
        "Development plan for {} roll(s)".format(len(rolls)),
    ]
    for roll, (process, seconds) in zip(rolls, develop(rolls)):
        lines.append(
            "  {:<24} -> {:<8} {}".format(
                normalize(roll),
                process,
                format_duration(seconds),
            )
        )
    for process in sorted(summarize(rolls)):
        count, total = summarize(rolls)[process]
        lines.append(
            "  {} batches in {}: {}".format(
                count,
                process,
                format_duration(total),
            )
        )
    return "\n".join(lines)


def main():
    darkroom_queue = [
        "color negative",
        "black and white classic",
        "Color Reversal",
        "infrared",
        "motion-picture",
        "color negative",
    ]
    print(develop(["color negative", "black and white classic"]))
    print(report(darkroom_queue))


if __name__ == "__main__":
    main()

