WAVEFORM_PROPERTIES = {
    "sine wave": (
        "odd harmonics",
        "smooth attack",
    ),
    "square wave": (
        "odd harmonics",
        "sudden attack",
    ),
    "sawtooth wave": (
        "odd and even harmonics",
        "sudden attack",
    ),
    "triangle wave": (
        "odd harmonics",
        "rapid roll off attack",
    ),
    "pulse wave": (
        "even harmonics",
        "sharp attack",
    ),
    "white noise": (
        "all harmonics",
        "random attack",
    ),
    "pink noise": (
        "low frequency harmonics",
        "random attack",
    ),
    "super saw": (
        "multiple detuned harmonics",
        "thick attack",
    ),
}


def normalize_name(name):
    return " ".join(str(name).lower().split())


def validate(signal):
    if not isinstance(signal, (tuple, list)) or len(signal) != 2:
        raise ValueError("each signal must be a (waveform, frequency) pair")
    waveform = normalize_name(signal[0])
    if waveform not in WAVEFORM_PROPERTIES:
        raise KeyError("unknown waveform: {0!r}".format(signal[0]))
    frequency = signal[1]
    if not isinstance(frequency, (int, float)) or isinstance(frequency, bool):
        raise ValueError("frequency must be numeric")
    if frequency <= 0:
        raise ValueError("frequency must be positive")
    return waveform, frequency


def modulate(signals):
    processed = []
    for signal in signals:
        waveform, frequency = validate(signal)
        harmonics, attack = WAVEFORM_PROPERTIES[waveform]
        processed.append((
            frequency,
            harmonics,
            attack,
        ))
    return processed


def format_report(signals):
    lines = []
    for (waveform, _), (frequency, harmonics, attack) in zip(signals, modulate(signals)):
        lines.append(
            "{0:>14} @ {1:>7.2f} Hz -> {2}, {3}".format(
                normalize_name(waveform),
                float(frequency),
                harmonics,
                attack,
            )
        )
    return "\n".join(lines)


def main():
    patch = [
        ("sine wave", 440),
        ("Square Wave", 220.5),
        ("sawtooth wave", 110),
        ("super saw", 55),
        ("pink noise", 1000),
    ]
    print(format_report(patch))
    print(modulate([("sine wave", 440)]))


if __name__ == "__main__":
    main()

