CATALOG = {
    "starter": (10, 20, 10),
    "vegetative": (20, 10, 10),
    "flowering": (10, 10, 20),
    "balanced": (15, 15, 15),
    "fruiting": (5, 15, 25),
    "root growth": (5, 25, 5),
    "winterizing": (5, 10, 20),
    "transition": (12, 12, 12),
}

NUTRIENTS = (
    "nitrogen",
    "phosphorus",
    "potassium",
)


def normalize(name):
    return " ".join(str(name).strip().lower().split())


def fertilize(crops):
    blends = []
    for crop in crops:
        key = normalize(crop)
        if key not in CATALOG:
            raise KeyError("unknown blend: {0!r}".format(crop))
        blends.append(CATALOG[key])
    return blends


def describe(blend):
    return "-".join(str(value) for value in blend)


def nutrient_totals(blends):
    return {
        name: sum(blend[index] for blend in blends)
        for index, name in enumerate(NUTRIENTS)
    }


def dominant_nutrient(blend):
    pairs = sorted(
        zip(NUTRIENTS, blend),
        key=lambda pair: (-pair[1], pair[0]),
    )
    return pairs[0][0]


def report(crops):
    blends = fertilize(crops)
    lines = [
        "{0:<12} {1:<10} {2}".format("BLEND", "N-P-K", "DOMINANT"),
    ]
    for crop, blend in zip(crops, blends):
        lines.append(
            "{0:<12} {1:<10} {2}".format(
                normalize(crop),
                describe(blend),
                dominant_nutrient(blend),
            )
        )
    totals = nutrient_totals(blends)
    lines.append("")
    for name in NUTRIENTS:
        lines.append("total {0}: {1}%".format(name, totals[name]))
    return "\n".join(lines)


def main():
    requested = [
        "starter",
        "Flowering",
        "root growth",
        "transition",
    ]
    print(report(requested))


if __name__ == "__main__":
    main()

