"""Primary exhaust products for common rocket propellant combinations."""

ALIASES = {
    "lox": "liquid oxygen",
    "lh2": "liquid hydrogen",
    "rp-1": "kerosene",
    "n2o4": "nitrogen tetroxide",
    "n2o": "nitrous oxide",
    "htpb": "solid rubber",
    "lf2": "liquid fluorine",
    "h2o2": "hydrogen peroxide",
    "ch4": "methane",
}

EXHAUST_PRODUCTS = {
    ("liquid hydrogen", "liquid oxygen"): "water vapor",
    ("kerosene", "liquid oxygen"): "carbon dioxide",
    ("hydrazine", "nitrogen tetroxide"): "nitrogen gas",
    ("nitrous oxide", "solid rubber"): "mixed exhaust",
    ("liquid fluorine", "liquid hydrogen"): "hydrogen fluoride",
    ("hydrogen peroxide", "kerosene"): "steam and carbon dioxide",
    ("liquid oxygen", "methane"): "carbon dioxide and water",
    ("aerozine", "nitrogen tetroxide"): "nitrogen and water",
}


def normalize(propellant):
    name = " ".join(str(propellant).split()).lower()
    return ALIASES.get(name, name)


def pair_key(first, second):
    return tuple(sorted((normalize(first), normalize(second))))


def exhaust_of(first, second):
    return EXHAUST_PRODUCTS.get(pair_key(first, second))


def launch(stages):
    products = []
    for first, second in stages:
        product = exhaust_of(first, second)
        if product is not None:
            products.append(product)
    return products


def unrecognized(stages):
    return [pair_key(a, b) for a, b in stages if exhaust_of(a, b) is None]


def tally(products):
    counts = {}
    for product in products:
        counts[product] = counts.get(product, 0) + 1
    return counts


def format_report(name, stages):
    products = launch(stages)
    lines = [
        "Mission: {}".format(name),
        "Stages fired: {}".format(len(stages)),
        "Exhaust: {}".format(", ".join(products) or "none"),
    ]
    for product, count in sorted(tally(products).items()):
        lines.append("  {:<26} x{}".format(product, count))
    for first, second in unrecognized(stages):
        lines.append("  ! unknown combination: {} + {}".format(first, second))
    return "\n".join(lines)


MISSIONS = {
    "Saturn V": [
        ("liquid oxygen", "kerosene"),
        ("lox", "lh2"),
        ("LOX", "liquid hydrogen"),
    ],
    "Titan II": [
        ("aerozine", "nitrogen tetroxide"),
        ("hydrazine", "n2o4"),
    ],
    "Experimental": [
        ("liquid fluorine", "liquid hydrogen"),
        ("h2o2", "rp-1"),
        ("lox", "ch4"),
        ("nitrous oxide", "htpb"),
        ("compressed air", "water"),
    ],
}


def main():
    for name, stages in MISSIONS.items():
        print(format_report(name, stages))
        print()
    print(launch([
        ("liquid oxygen", "liquid hydrogen"),
    ]))


if __name__ == "__main__":
    main()

