    ("whorled", "heart shaped"): "catalpa tree",
    ("opposite", "pinnately compound"): "ash tree",
    ("alternate", "pinnately compound"): "hickory tree",
    ("fascicled", "needle like"): "pine tree",
}

SHAPE_ONLY_DATABASE = {
    "scale like overlapping": "cedar tree",
    "scale like": "cedar tree",
}

SHAPE_ALIASES = {
    "oval": "oval serrated",
    "serrated": "oval serrated",
    "heart": "heart shaped",
    "needle": "needle like",
    "needles": "needle like",
    "compound": "pinnately compound",
    "scaly overlapping": "scale like overlapping",
}

UNKNOWN = "unknown tree"


def _normalize(text):
    if not isinstance(text, str):
        raise TypeError("leaf descriptions must be strings, got {!r}".format(text))
    cleaned = text.strip().lower()
    for token in ("-", "_", ",",):
        cleaned = cleaned.replace(token, " ")
    return " ".join(cleaned.split())


def _canonical_shape(shape):
    normalized = _normalize(shape)
    return SHAPE_ALIASES.get(normalized, normalized)


def identify(trees):
    names = []
    for arrangement, shape in trees:
        key = (_normalize(arrangement), _canonical_shape(shape))
        if key in TREE_DATABASE:
            names.append(TREE_DATABASE[key])
        else:
            names.append(SHAPE_ONLY_DATABASE.get(key[1], UNKNOWN))
    return names


def describe(trees):
    lines = []
    for (arrangement, shape), name in zip(trees, identify(trees)):
        lines.append("{:>10} / {:<20} -> {}".format(
            _normalize(arrangement),
            _canonical_shape(shape),
            name,
        ))
    return lines


def summarize(trees):
    counts = {}
    for name in identify(trees):
        counts[name] = counts.get(name, 0) + 1
    return counts


def main():
