text_nat:
CLOUD_DATA = {
    "cirrus": ("high", "wispy", "none"),
    "stratus": ("low", "flat", "light"),
    "cumulus": ("low", "puffy", "none"),
    "nimbus": ("low", "dark", "heavy"),
    "altocumulus": ("middle", "patched", "none"),
    "cirrostratus": ("high", "halo", "none"),
    "stratocumulus": ("low", "lumpy", "light"),
    "cumulonimbus": ("vertical", "towering", "heavy"),
}

UNKNOWN = ("unknown", "unknown", "unknown")

PRECIPITATION_ORDER = [
    "none",
    "light",
    "heavy",
    "unknown",
]


def weather(cloud):
    """Return (altitude, shape, precipitation) for the named cloud."""
    if not isinstance(cloud, str):
        return UNKNOWN
    return CLOUD_DATA.get(cloud.strip().lower(), UNKNOWN)


def describe(cloud):
    """Build a one-sentence description of the given cloud."""
    altitude, shape, precipitation = weather(cloud)
    if altitude == "unknown":
        return "{0} is not a recognised cloud type.".format(cloud)
    rainfall = {
        "none": "brings no precipitation",
        "light": "brings light precipitation",
        "heavy": "brings heavy precipitation",
    }[precipitation]
    return "{0} sits at {1} altitude, looks {2} and {3}.".format(
        cloud,
        altitude,
        shape,
        rainfall,
    )


def group_by_altitude(clouds):
    """Map each altitude category to the sorted clouds found at it."""
    grouped = {}
    for cloud in clouds:
        altitude = weather(cloud)[0]
        grouped.setdefault(altitude, []).append(cloud)
    return {key: sorted(value) for key, value in grouped.items()}


def wettest(clouds):
    """Return the cloud with the strongest precipitation likelihood."""
    ranked = sorted(
        clouds,
        key=lambda cloud: PRECIPITATION_ORDER.index(weather(cloud)[2]),
        reverse=True,
    )
    return ranked[0] if ranked else None


def main():
    samples = [
        "cirrus",
        "Stratocumulus",
        "cumulonimbus",
        "altocumulus",
        "fogbank",
    ]
    for cloud in samples:
        print(describe(cloud))
    for altitude, members in sorted(group_by_altitude(samples).items()):
        print("{0}: {1}".format(altitude, ", ".join(members)))
    print("wettest sample:", wettest(samples))


if __name__ == "__main__":
    main()

