    "arrabbiata": ("tomato", "chili", "medium"),
    "puttanesca": ("tomato", "capers", "medium"),
    "vodka": ("cream and tomato", "basil", "medium"),
}

THICKNESS_ORDER = [
    "thin",
    "medium",
    "thick",
]


def sauce(name):
    """Return (base liquid, primary herb, thickness) for the named sauce."""
    if not isinstance(name, str):
        return (UNKNOWN, UNKNOWN, UNKNOWN)
    return SAUCE_TABLE.get(name.strip().lower(), (UNKNOWN, UNKNOWN, UNKNOWN))


def describe(name):
    """Build a one-line human readable description of a sauce."""
    base, herb, thickness = sauce(name)
    if base == UNKNOWN:
        return "{0}: unknown sauce".format(name)
    return "{0}: {1} base with {2}, {3} texture".format(
        name.strip().lower(),
        base,
        herb,
        thickness,
    )


def group_by_thickness(names):
    """Map each known thickness profile to the sauces that share it."""
    groups = {key: [] for key in THICKNESS_ORDER}
    for name in names:
        base, _herb, thickness = sauce(name)
        if base != UNKNOWN:
            groups[thickness].append(name.strip().lower())
    return {key: sorted(groups[key]) for key in THICKNESS_ORDER}


def herbs_in_common(first, second):
    """Return the herbs shared by two sauces, ignoring unknown entries."""
    herbs = {
        sauce(first)[1],
        sauce(second)[1],
    }
    herbs.discard(UNKNOWN)
    if len(herbs) == 2:
        return []
    return sorted(herbs)


