"""Anniversary traditions: traditional gift, modern alternative, symbolic colour."""

UNKNOWN = ("unknown", "unknown", "unknown")

ANNIVERSARY_GIFTS = {
    1: ("paper", "clocks", "yellow"),
    2: ("cotton", "china", "red"),
    3: ("leather", "crystal", "white"),
    4: ("fruit", "appliances", "blue"),
    5: ("wood", "silverware", "pink"),
    6: ("iron", "wood", "purple"),
    7: ("copper", "desk sets", "yellow"),
    8: ("bronze", "linens", "bronze"),
}

COLUMNS = [
    ("Year", 6),
    ("Traditional", 14),
    ("Modern", 14),
    ("Colour", 10),
]


def anniversary(year):
    """Return (traditional, modern, colour) for the given anniversary year."""
    if isinstance(year, bool) or not isinstance(year, int):
        raise TypeError("year must be an integer")
    return ANNIVERSARY_GIFTS.get(year, UNKNOWN)


def gift_details(year):
    """Return a mapping of field name to value for one anniversary year."""
    traditional, modern, colour = anniversary(year)
    return {
        "year": year,
        "traditional": traditional,
        "modern": modern,
        "colour": colour,
    }


def describe(year):
    """Return a one-line human readable summary of an anniversary year."""
    details = gift_details(year)
    parts = [
        "Year {year}".format(**details),
        "traditional: {traditional}".format(**details),
        "modern: {modern}".format(**details),
        "colour: {colour}".format(**details),
    ]
    return " | ".join(parts)


def build_table(years):
    """Return a list of text lines tabulating the given anniversary years."""
    widths = [width for _, width in COLUMNS]
    header = "".join(name.ljust(width) for name, width in COLUMNS)
    lines = [
        header,
        "-" * sum(widths),
    ]
    for year in years:
        cells = [str(year), *anniversary(year)]
        lines.append("".join(cell.ljust(width) for cell, width in zip(cells, widths)))
    return lines


def main():
    for line in build_table(range(1, 10)):
        print(line)
    print()
    for year in [5, 8, 25]:
        print(describe(year))


if __name__ == "__main__":
    main()

