    "solid": "reactive solid",
    "pearl": "reactive pearl",
    "hybrid": "reactive hybrid",
    "poly": "plastic",
    "polyester": "plastic",
}


def normalize(cover):
    """Reduce a user-supplied coverstock name to a canonical dictionary key."""
    if not isinstance(cover, str):
        return ""
    key = " ".join(cover.lower().replace("-", " ").replace("_", " ").split())
    return ALIASES.get(key, key)


def bowling(cover):
    """Return (friction, durability, hook potential) for a bowling coverstock."""
    return COVERSTOCKS.get(normalize(cover), UNKNOWN)


def describe(cover):
    """Build a labelled mapping of the properties of one coverstock."""
    friction, durability, hook = bowling(cover)
    return {
        "coverstock": cover,
        "friction": friction,
        "durability": durability,
        "hook": hook,
