    cleaned = " ".join(str(size).strip().lower().split())
    return SIZE_ALIASES.get(cleaned, cleaned)


def mattress(size):
    return MATTRESS_SIZES.get(normalize(size), (0, 0))


def fitted_sheet(size):
    width, length = mattress(size)
    if (width, length) == (0, 0):
        return (0, 0)
    return (
        width + 2 * POCKET_DEPTH,
        length + 2 * POCKET_DEPTH,
    )


