text_nat:
ROOMS = {
    "library": {
        "par_minutes": 20,
        "hint_allowance": 2,
    },
    "laboratory": {
        "par_minutes": 30,
        "hint_allowance": 3,
    },
    "dungeon": {
        "par_minutes": 40,
        "hint_allowance": 1,
    },
    "vault": {
        "par_minutes": 15,
        "hint_allowance": 0,
    },
}


def room_data(name):
    key = str(name).strip().lower()
    if key not in ROOMS:
        raise ValueError("unknown room: {0!r}".format(name))
    return key, ROOMS[key]


def score_attempt(name, minutes, hints):
    _, room = room_data(name)
    if minutes < room["par_minutes"]:
        return max(0, 100 - 10 * hints)
    return max(0, 50 - 20 * hints)


def score(attempts):
    return [score_attempt(name, minutes, hints) for name, minutes, hints in attempts]


def summarize(attempts):
    rows = []
    for name, minutes, hints in attempts:
        key, room = room_data(name)
        rows.append({
            "room": key,
            "minutes": minutes,
            "par_minutes": room["par_minutes"],
            "hints": hints,
            "over_allowance": hints > room["hint_allowance"],
            "points": score_attempt(name, minutes, hints),
        })
    return rows


def format_report(rows):
    lines = [
        "room        time   par  hints  points",
        "-" * 38,
    ]
    for row in rows:
        marker = "!" if row["over_allowance"] else " "
        lines.append("{0:<11} {1:>4}  {2:>4}  {3:>4}{4}  {5:>5}".format(
            row["room"],
            row["minutes"],
            row["par_minutes"],
            row["hints"],
            marker,
            row["points"],
        ))
    lines.append("total: {0}".format(sum(row["points"] for row in rows)))
    return lines


def main():
    attempts = [
        ("library", 25, 1),
        ("laboratory", 28, 2),
        ("dungeon", 41, 1),
        ("vault", 14, 0),
    ]
    print(score(attempts))
    for line in format_report(summarize(attempts)):
        print(line)


if __name__ == "__main__":
    main()

