        "small": 3.00,
        "medium": 4.00,
        "large": 4.50,
    },
    "mocha": {
        "small": 4.00,
        "medium": 5.00,
        "large": 6.00,
    },
}

MILK_SURCHARGES = {
    "whole": 0.00,
    "skim": 0.00,
    "soy": 0.50,
    "oat": 0.75,
    "almond": 0.50,
}


def price_of(beverage, size, milk):
    name = beverage.strip().lower()
    cup = size.strip().lower()
    dairy = milk.strip().lower()
    if name not in MENU:
        raise ValueError("unknown beverage: {}".format(beverage))
    if cup not in MENU[name]:
        raise ValueError("unknown size: {}".format(size))
    if dairy not in MILK_SURCHARGES:
        raise ValueError("unknown milk: {}".format(milk))
    return MENU[name][cup] + MILK_SURCHARGES[dairy]


def calculate(order):
    return float(sum(price_of(*item) for item in order))


