ATMOSPHERE_RULES = {
    "nitrogen oxygen": (-20, 40),
    "carbon dioxide": (-50, 10),
    "methane": (-100, -50),
    "argon": (0, 50)
}

ROW_TEMPLATE = "{name:<10} {atmosphere:<16} {temperature:>7} water={water!s:<5} {verdict}"

HEADER = ROW_TEMPLATE.format(
    name="PLANET",
    atmosphere="ATMOSPHERE",
    temperature="TEMP",
    water="Y/N",
    verdict="VERDICT"
)


def normalize_atmosphere(atmosphere):
    return " ".join(str(atmosphere).lower().replace("-", " ").replace("_", " ").split())


def temperature_ok(atmosphere, temperature):
    bounds = ATMOSPHERE_RULES.get(normalize_atmosphere(atmosphere))
    if bounds is None:
        return False
    low, high = bounds
    return low < temperature < high


def is_viable(planet):
    name, atmosphere, temperature, has_water = planet
    return bool(name) and bool(has_water) and temperature_ok(atmosphere, temperature)


def assess(planets):
    return [planet[0] for planet in planets if is_viable(planet)]


def describe(planet):
    name, atmosphere, temperature, has_water = planet
    key = normalize_atmosphere(atmosphere)
    bounds = ATMOSPHERE_RULES.get(key)
    if bounds is None:
        reason = "unknown atmosphere {!r}".format(atmosphere)
    elif not has_water:
        reason = "no water detected"
    elif not temperature_ok(atmosphere, temperature):
        reason = "temperature outside ({}, {})".format(*bounds)
    else:
        reason = "viable"
    return {
        "name": name,
        "atmosphere": key,
        "temperature": "{}C".format(temperature),
        "water": bool(has_water),
        "verdict": reason
    }


def report(planets):
    lines = [HEADER]
    for planet in planets:
        lines.append(
            ROW_TEMPLATE.format(
                **describe(planet)
            )
        )
    return "\n".join(lines)


def summarize(planets):
    details = [describe(planet) for planet in planets]
    return {
        "surveyed": len(details),
        "viable": [item["name"] for item in details if item["verdict"] == "viable"],
        "rejected": [item["name"] for item in details if item["verdict"] != "viable"]
    }


def main():
    survey = [
        ("Eden", "nitrogen oxygen", 20, True),
        ("Vulcan", "carbon dioxide", 5, True),
        ("Titan II", "methane", -70, True),
        ("Arid", "argon", 25, False),
        ("Frostbite", "nitrogen oxygen", -20, True),
        ("Kepler 9", "hydrogen", 12, True)
    ]
    print(report(survey))
    summary = summarize(survey)
    print("Surveyed {surveyed}, viable {viable}".format(**summary))
    print("Rejected:", ", ".join(summary["rejected"]))
    print(assess([("Eden", "nitrogen oxygen", 20, True)]))


if __name__ == "__main__":
    main()

