REQUIREMENTS = {
    "tomatoes": {
        "nitrogen": 2,
        "phosphorus": 1,
        "potassium": 2,
    },
    "carrots": {
        "nitrogen": 1,
        "phosphorus": 2,
        "potassium": 1,
    },
    "beans": {
        "nitrogen": 0,
        "phosphorus": 1,
        "potassium": 1,
    },
    "corn": {
        "nitrogen": 3,
        "phosphorus": 2,
        "potassium": 1,
    },
}

NUTRIENTS = (
    "nitrogen",
    "phosphorus",
    "potassium",
)


def normalize(plant):
    """Return the canonical plant-type key, or raise for unknown types."""
    key = str(plant).strip().lower()
    if key not in REQUIREMENTS:
        raise ValueError("unknown plant type: {!r}".format(plant))
    return key


def formulate(plants):
    """Total nitrogen, phosphorus and potassium needed for the given plots."""
    totals = dict.fromkeys(NUTRIENTS, 0)
    for plant, area in plants:
        if area < 0:
            raise ValueError("area must be non-negative, got {!r}".format(area))
        needs = REQUIREMENTS[normalize(plant)]
        for nutrient in NUTRIENTS:
            totals[nutrient] += needs[nutrient] * area
    return tuple(totals[nutrient] for nutrient in NUTRIENTS)


def summarize(plants):
    """Build a per-plot report plus the aggregated totals."""
    rows = [
        (normalize(plant), area, formulate([(plant, area)]))
        for plant, area in plants
    ]
    return {
        "rows": rows,
        "totals": formulate(plants),
    }


def render(report):
    lines = [
        "{:<10} {:>6} {:>6} {:>6} {:>6}".format(
            "plant", "area", "N", "P", "K",
        ),
    ]
    for plant, area, (n, p, k) in report["rows"]:
        lines.append("{:<10} {:>6} {:>6} {:>6} {:>6}".format(plant, area, n, p, k))
    n, p, k = report["totals"]
    lines.append("{:<10} {:>6} {:>6} {:>6} {:>6}".format("TOTAL", "", n, p, k))
    return "\n".join(lines)


def main():
    garden = [
        ("tomatoes", 10),
        ("carrots", 4),
        ("beans", 7),
        ("corn", 12),
    ]
    print(render(summarize(garden)))
    print("single plot:", formulate([("tomatoes", 10)]))


if __name__ == "__main__":
    main()

