        "vegetation": 5
    },
    "monkey": {
        "meat": 1,
        "vegetation": 3
    }
}

BULK_RULES = {
    "meat": (20, 18),
    "vegetation": (30, 25)
}


def bulk_amount(kind, kilograms):
    block, discounted = BULK_RULES[kind]
    blocks, remainder = divmod(kilograms, block)
    return blocks * discounted + remainder


def raw_totals(animals):
    totals = {
        "meat": 0,
        "vegetation": 0
    }
    unknown = sorted({str(name) for name in animals if str(name).lower() not in RATIONS})
    if unknown:
        raise ValueError("unknown species: " + ", ".join(unknown))
    for name in animals:
        ration = RATIONS[str(name).lower()]
        totals["meat"] += ration["meat"]
        totals["vegetation"] += ration["vegetation"]
    return totals


def feed(animals):
    totals = raw_totals(animals)
    return (
        bulk_amount("meat", totals["meat"]),
        bulk_amount("vegetation", totals["vegetation"])
    )


def format_report(animals):
    totals = raw_totals(animals)
    meat, vegetation = feed(animals)
    lines = [
        "animals: " + (", ".join(sorted(animals)) or "none"),
        "required meat: {} kg -> purchased {} kg".format(totals["meat"], meat),
        "required vegetation: {} kg -> purchased {} kg".format(totals["vegetation"], vegetation)
    ]
    return "\n".join(lines)


def main():
    orders = [
        ["lion", "lion"],
        ["zebra", "zebra", "zebra"],
        ["bear", "monkey", "monkey", "lion"],
        []
    ]
    for order in orders:
        print(format_report(order))
        print("total:", feed(order))
        print()
    try:
        feed(["lion", "dragon", "yeti"])
    except ValueError as error:
        print("rejected order:", error)


if __name__ == "__main__":
    main()

