        "languages": frozenset({
            "html",
            "css",
            "javascript",
        }),
        "experience": 2,
    },
    "backend": {
        "languages": frozenset({"python", "sql", "linux"}),
        "experience": 3,
    },
    "mobile": {
        "languages": frozenset({"swift", "kotlin", "java"}),
        "experience": 1,
    },
    "data": {
        "languages": frozenset({"python", "r", "sql"}),
        "experience": 4,
    },
}

ROLE_ORDER = (
    "frontend",
    "backend",
    "mobile",
    "data",
)


def parse_candidate(candidate):
    name, years, languages = candidate
    if years < 0:
        raise ValueError("years of experience cannot be negative: {0!r}".format(name))
    known = {str(language).strip().lower() for language in languages}
    return str(name).strip(), int(years), known


def qualifies(role, years, known):
    spec = ROLES[role]
    return years >= spec["experience"] and spec["languages"] <= known


def screen(candidates):
    results = []
    for candidate in candidates:
        name, years, known = parse_candidate(candidate)
        matched = [role for role in ROLE_ORDER if qualifies(role, years, known)]
        results.append((name, matched))
    return results


def format_report(results):
    lines = [
