INVENTORY = {
    "single": 10,
    "double": 5,
    "suite": 2,
}

PRICES = {
    "single": 100,
    "double": 150,
    "suite": 300,
}


def reserve(requests):
    availability = dict(INVENTORY)
    confirmed = []
    for guest, room_type, nights in requests:
        if availability.get(room_type, 0) > 0:
            availability[room_type] -= 1
            confirmed.append((guest, room_type, PRICES[room_type] * nights))
    return confirmed


def validate(requests):
    problems = []
    for index, request in enumerate(requests):
        if len(request) != 3:
            problems.append((index, "expected (guest, room_type, nights)"))
            continue
        guest, room_type, nights = request
        if not isinstance(guest, str) or not guest.strip():
            problems.append((index, "guest name must be a non-empty string"))
        if room_type not in PRICES:
            problems.append((index, "unknown room type: {!r}".format(room_type)))
        if not isinstance(nights, int) or nights < 1:
            problems.append((index, "nights must be a positive integer"))
    return problems


def summarize(bookings):
    summary = {
        "count": len(bookings),
        "revenue": sum(cost for _, _, cost in bookings),
        "by_type": {},
    }
    for _, room_type, cost in bookings:
        entry = summary["by_type"].setdefault(room_type, {
            "units": 0,
            "revenue": 0,
        })
        entry["units"] += 1
        entry["revenue"] += cost
    return summary


def format_report(bookings, summary):
    lines = [
        "CONFIRMED BOOKINGS",
        "-" * 40,
    ]
    for guest, room_type, cost in bookings:
        lines.append("{:<12} {:<8} ${:>6}".format(guest, room_type, cost))
    lines.extend([
        "-" * 40,
        "fulfilled: {}".format(summary["count"]),
        "revenue:   ${}".format(summary["revenue"]),
    ])
    for room_type in sorted(summary["by_type"]):
        entry = summary["by_type"][room_type]
        lines.append("  {}: {} unit(s), ${}".format(room_type, entry["units"], entry["revenue"]))
    return "\n".join(lines)


def main():
    requests = [
        ("Alice", "single", 2),
        ("Bob", "suite", 3),
        ("Cara", "suite", 1),
        ("Dan", "suite", 4),
        ("Eve", "double", 5),
    ]
    for index, message in validate(requests):
        print("request {}: {}".format(index, message))
    bookings = reserve(requests)
    print(format_report(bookings, summarize(bookings)))


if __name__ == "__main__":
    main()

