TRUCK_BY_NEIGHBORHOOD = {
    "northside": "truck one",
    "southside": "truck two",
    "eastside": "truck three",
    "westside": "truck four",
}

TRUCK_CAPACITY = {
    "truck one": 500,
    "truck two": 600,
    "truck three": 400,
    "truck four": 700,
}


def normalize(parcel):
    identifier, neighborhood, weight = parcel
    return (
        identifier,
        str(neighborhood).strip().lower(),
        float(weight),
    )


def manifest(parcels):
    loads = {truck: 0.0 for truck in TRUCK_CAPACITY}
    per_truck = {truck: [] for truck in TRUCK_CAPACITY}
    assigned = []
    unassigned = []
    for parcel in parcels:
        identifier, neighborhood, weight = normalize(parcel)
        truck = TRUCK_BY_NEIGHBORHOOD.get(neighborhood)
        if truck is None or loads[truck] + weight > TRUCK_CAPACITY[truck]:
            unassigned.append(identifier)
            continue
        loads[truck] += weight
        per_truck[truck].append(identifier)
        assigned.append(identifier)
    return {
        "loads": loads,
        "per_truck": per_truck,
        "assigned": assigned,
        "unassigned": unassigned,
    }


def route(parcels):
    return manifest(parcels)["assigned"]


def report(parcels):
    summary = manifest(parcels)
    lines = []
    for truck, capacity in TRUCK_CAPACITY.items():
        lines.append("{}: {:.0f}/{} -> {}".format(
            truck,
            summary["loads"][truck],
            capacity,
            ", ".join(summary["per_truck"][truck]) or "empty",
        ))
    lines.append("unassigned: " + (", ".join(summary["unassigned"]) or "none"))
    return "\n".join(lines)


def main():
    shipment = [
        ("P1", "northside", 100),
        ("P2", "northside", 450),
        ("P3", "southside", 600),
        ("P4", "eastside", 250),
        ("P5", "Eastside", 200),
        ("P6", "westside", 700),
        ("P7", "downtown", 50),
    ]
    print(route(shipment))
    print(report(shipment))


if __name__ == "__main__":
    main()

