text_nat:
PASTRIES = {
    "croissant": {
        "prep": 45,
        "bake": 20,
    },
    "muffin": {
        "prep": 15,
        "bake": 25,
    },
    "tart": {
        "prep": 30,
        "bake": 35,
    },
    "cookie": {
        "prep": 10,
        "bake": 12,
    },
}


def _lookup(name):
    key = str(name).strip().lower()
    if key not in PASTRIES:
        raise ValueError("unknown pastry: {!r}".format(name))
    return key


def timeline(orders):
    """Return a per-item schedule for one prep station and one oven."""
    prep_free = 0
    oven_free = 0
    steps = []
    for name in orders:
        key = _lookup(name)
        prep_start = max(prep_free, oven_free)
        prep_end = prep_start + PASTRIES[key]["prep"]
        bake_start = max(prep_end, oven_free)
        finish = bake_start + PASTRIES[key]["bake"]
        steps.append({
            "pastry": key,
            "prep_start": prep_start,
            "bake_start": bake_start,
            "finish": finish,
        })
        prep_free = prep_end
        oven_free = finish
    return steps


def schedule(orders):
    return [step["finish"] for step in timeline(orders)]


def summarize(orders):
    steps = timeline(orders)
    return {
        "items": len(steps),
        "batch_finish": steps[-1]["finish"] if steps else 0,
        "oven_minutes": sum(PASTRIES[s["pastry"]]["bake"] for s in steps),
    }


def format_report(orders):
    lines = [
        "{:<10}{:>6}{:>6}{:>6}".format("pastry", "prep", "oven", "done"),
        "-" * 28,
    ]
    for step in timeline(orders):
        lines.append("{:<10}{:>6}{:>6}{:>6}".format(
            step["pastry"],
            step["prep_start"],
            step["bake_start"],
            step["finish"],
        ))
    totals = summarize(orders)
    lines.append("batch of {items} done at {batch_finish} min".format(**totals))
    return "\n".join(lines)


def main():
    batches = [
        ["cookie", "muffin"],
        ["croissant", "tart", "cookie", "muffin"],
    ]
    for batch in batches:
        print(", ".join(batch))
        print(format_report(batch))
        print("finish times:", schedule(batch))
        print()


if __name__ == "__main__":
    main()

