import math

EVENT_SPECS = {
    "wedding": {
        "attendees_per_table": 10,
        "chairs_per_attendee": 1,
        "speakers": 2,
    },
    "conference": {
        "attendees_per_table": 20,
        "chairs_per_attendee": 1,
        "speakers": 4,
    },
    "concert": {
        "attendees_per_table": None,
        "chairs_per_attendee": 0,
        "speakers": 10,
    },
    "banquet": {
        "attendees_per_table": 8,
        "chairs_per_attendee": 1,
        "speakers": 1,
    },
}


def requirements(event_type, attendees):
    spec = EVENT_SPECS[event_type]
    per_table = spec["attendees_per_table"]
    tables = 0 if per_table is None else math.ceil(attendees / per_table)
    return (
        tables,
        attendees * spec["chairs_per_attendee"],
        spec["speakers"],
    )


def validate(events):
    checked = []
    for event_type, attendees in events:
        key = event_type.strip().lower()
        if key not in EVENT_SPECS:
            raise ValueError("unknown event type: " + event_type)
        if attendees < 0:
            raise ValueError("attendees must not be negative")
        checked.append((key, attendees))
    return checked


def plan(events):
    tables = chairs = speakers = 0
    for event_type, attendees in validate(events):
        event_tables, event_chairs, event_speakers = requirements(event_type, attendees)
        tables += event_tables
        chairs += event_chairs
        speakers += event_speakers
    return (tables, chairs, speakers)


def report(events):
    lines = []
    for event_type, attendees in validate(events):
        tables, chairs, speakers = requirements(event_type, attendees)
        lines.append(
            "{:<12} {:>5} attendees -> {:>4} tables, {:>4} chairs, {:>3} speakers".format(
                event_type, attendees, tables, chairs, speakers,
            )
        )
    totals = plan(events)
    lines.append("{:<12} {:>5} {:>13} {:>4} tables, {:>4} chairs, {:>3} speakers".format(
        "TOTAL", "", "", *totals,
    ))
    return "\n".join(lines)


def main():
    schedule = [
        ("banquet", 16),
        ("wedding", 135),
        ("conference", 240),
        ("concert", 4000),
    ]
    print(report(schedule))
    print()
    print("plan(single banquet):", plan([("banquet", 16)]))


if __name__ == "__main__":
    main()

