NUTRITION = {
    "burger": {
        "calories": 500,
        "fat": 20,
        "protein": 25,
    },
    "fries": {
        "calories": 300,
        "fat": 15,
        "protein": 3,
    },
    "soda": {
        "calories": 200,
        "fat": 0,
        "protein": 0,
    },
    "salad": {
        "calories": 100,
        "fat": 5,
        "protein": 2,
    },
}


def normalize(item):
    return item.strip().lower()


def meal_totals(meal):
    totals = {
        "calories": 0,
        "fat": 0,
        "protein": 0,
    }
    for item in meal:
        name = normalize(item)
        if name not in NUTRITION:
            raise KeyError("unknown food item: {!r}".format(item))
        facts = NUTRITION[name]
        for key in totals:
            totals[key] += facts[key]
    return (
        totals["calories"],
        totals["fat"],
        totals["protein"],
    )


def analyze(meals):
    return [meal_totals(meal) for meal in meals]


def format_report(meals, results):
    lines = []
    for index, (meal, totals) in enumerate(zip(meals, results), start=1):
        items = ", ".join(normalize(item) for item in meal) or "nothing"
        lines.append(
            "Meal {0}: {1} -> {2} cal, {3} g fat, {4} g protein".format(
                index,
                items,
                totals[0],
                totals[1],
                totals[2],
            )
        )
    return "\n".join(lines)


def main():
    orders = [
        ["burger", "fries"],
        ["salad", "soda"],
        ["burger", "burger", "fries", "soda"],
        [],
    ]
    results = analyze(orders)
    print(format_report(orders, results))
    print("Order totals:", results)


if __name__ == "__main__":
    main()

