COURSES = {
    "BIO101": {
        "name": "Biology",
        "category": "science",
        "credits": 3,
    },
    "MAT201": {
        "name": "Calculus",
        "category": "math",
        "credits": 4,
    },
    "LIT110": {
        "name": "Literature",
        "category": "humanities",
        "credits": 3,
    },
    "HIS105": {
        "name": "History",
        "category": "humanities",
        "credits": 2,
    },
}

REQUIRED_CATEGORIES = (
    "science",
    "math",
    "humanities",
)

MINIMUM_CREDITS = 10


def summarize(codes):
    earned = set()
    for code in codes:
        key = code.strip().upper()
        if key in COURSES:
            earned.add(key)
    return {
        "credits": sum(COURSES[key]["credits"] for key in earned),
        "categories": {COURSES[key]["category"] for key in earned},
        "titles": sorted(COURSES[key]["name"] for key in earned),
    }


def qualifies(summary):
    has_all = all(cat in summary["categories"] for cat in REQUIRED_CATEGORIES)
    return has_all and summary["credits"] >= MINIMUM_CREDITS


def evaluate(transcripts):
    graduates = []
    for name, codes in transcripts:
        if qualifies(summarize(codes)):
            graduates.append(name)
    return graduates


def report(transcripts):
    lines = []
    for name, codes in transcripts:
        summary = summarize(codes)
        missing = [
            category
            for category in REQUIRED_CATEGORIES
            if category not in summary["categories"]
        ]
        status = "GRADUATE" if qualifies(summary) else "PENDING"
        detail = ", ".join(summary["titles"]) or "no recognized courses"
        lines.append(
            "{0:<8} {1:>2} credits  {2:<9} [{3}]{4}".format(
                name,
                summary["credits"],
                status,
                detail,
                " missing: " + "/".join(missing) if missing else "",
            )
        )
    return "\n".join(lines)


def main():
    transcripts = [
        ("Ana", ["BIO101", "MAT201", "LIT110", "HIS105"]),
        ("Ben", ["BIO101", "MAT201", "HIS105"]),
        ("Cleo", ["bio101", "mat201", "lit110", "ART999"]),
        ("Dan", ["LIT110", "HIS105"]),
    ]
    print(report(transcripts))
    print("Graduating:", ", ".join(evaluate(transcripts)))


if __name__ == "__main__":
    main()

