def tension_for(speed_kph):
    for (low, high), tension in LINE_TENSIONS.items():
        if low <= speed_kph < high:
            return tension
    raise ValueError("wind speed %r outside rated envelope" % speed_kph)


def classify(wind):
    missing = [field for field in REQUIRED_FIELDS if field not in wind]
    if missing:
        raise KeyError("missing weather statistics: " + ", ".join(missing))
    speed = wind["speed_kph"]
    tension = tension_for(speed)
    lines = wind["lines"]
    if speed >= 34 or wind["gust_kph"] - speed >= 20:
        architecture = "box"
