    surfaces = KITE_ARCHITECTURES[architecture]
    surface = SURFACE_BY_LINES.get(lines, "")
    if surface not in surfaces:
        surface = surfaces[-1] if tension.startswith("extreme") else surfaces[0]
    return (architecture, surface)


