}


def summarize(logs):
    depths = [entry["depth"] for entry in logs]
    return {
        "dives": len(logs),
        "max_depth": max(depths),
        "environments": sorted({entry["environment"] for entry in logs})
    }


def eligible_specialties(max_depth):
    return [name for name, limit in SPECIALTY_DEPTHS.items() if limit <= max_depth]


def route(diver):
    for field in ("certification", "logs"):
        if not diver.get(field):
            raise ValueError(f"diver history missing {field}")
    stats = summarize(diver["logs"])
    index = TIER_ORDER.index(diver["certification"])
    next_tier = TIER_ORDER[min(index + 1, len(TIER_ORDER) - 1)]
    skills = CERT_TIERS[next_tier]
    mastered = set(diver.get("skills", ()))
    pending = [skill for skill in skills if skill not in mastered]
    if stats["max_depth"] < SPECIALTY_DEPTHS["wreck"]:
        return (next_tier, skills[0])
