PRINCIPLE_PROPS = {
    'vanishing': ['coin', 'silk', 'birdcage', 'card', 'dove'],
    'production': ['top hat', 'rabbit', 'fan of cards', 'bouquet', 'egg bag'],
    'transposition': ['deck', 'envelope', 'trunk', 'handcuffs', 'assistant'],
    'restoration': ['rope', 'newspaper', 'torn card', 'ribbon', 'wand'],
    'levitation': ['table', 'floating ball', 'silk thread', 'sword', 'chair'],
    'penetration': ['linking rings', 'cups and balls', 'sword basket', 'zombie ball', 'coin'],
    'transformation': ['silk', 'canary', 'colour-changing deck', 'wine glass', 'paper flower'],
}

PRINCIPLE_CUES = {
    'vanishing': ['disappear', 'vanish', 'gone', 'fades away'],
    'production': ['appears', 'produce', 'pulls out', 'materialises'],
    'transposition': ['swap', 'switch places', 'travels', 'exchange'],
    'restoration': ['restored', 'made whole', 'mended', 'cut and rejoined'],
    'levitation': ['floats', 'levitate', 'rises', 'hovers'],
    'penetration': ['passes through', 'penetrate', 'solid through solid', 'links'],
    'transformation': ['changes into', 'transform', 'becomes', 'turns into'],
}

MISDIRECTION_TRIGGERS = {
    'gaze direction': 'spectators instinctively look where the performer looks',
    'timing offbeat': 'attention relaxes the instant the effect seems finished',
    'large motion cover': 'a big gesture masks a smaller secret one',
    'verbal patter': 'language loads working memory and blurs the timeline',
    'audience participation': 'a volunteer draws every eye away from the hands',
    'false transfer': 'the mind accepts an implied action it never truly saw',
    'sound cue': 'a sharp noise anchors belief in an object that has already left',
}


def _as_elements(illusion):
    if isinstance(illusion, str):
        return {'description': illusion.lower(), 'props': [], 'technique': None}
    return {
        'description': str(illusion.get('description', '')).lower(),
        'props': [str(prop).lower() for prop in illusion.get('props', [])],
        'technique': illusion.get('technique'),
    }


def classify_principle(description):
    scores = {}
    for principle, cues in PRINCIPLE_CUES.items():
        hits = sum(1 for cue in cues if cue in description)
        if hits:
            scores[principle] = hits
    if not scores:
        return 'unclassified'
    return max(scores, key=lambda name: scores[name])


def identify_prop(description, props, principle):
    catalogue = PRINCIPLE_PROPS.get(principle, [])
    for prop in props:
        if prop in catalogue:
            return prop
    for prop in catalogue:
        if prop in description:
            return prop
    return props[0] if props else 'bare hands'


def reveal(illusion):
    elements = _as_elements(illusion)
    principle = classify_principle(elements['description'])
    prop = identify_prop(elements['description'], elements['props'], principle)
    return (principle, prop)


def report(illusion):
    principle, prop = reveal(illusion)
    technique = _as_elements(illusion)['technique']
    trigger = MISDIRECTION_TRIGGERS.get(technique, 'no documented psychological trigger')
    return '{0} via {1} -- {2}'.format(principle, prop, trigger)


if __name__ == '__main__':
    programme = [
        {
            'description': 'A borrowed coin disappear from the closed fist',
            'props': [
                'coin',
                'silk',
