    ],
    "trance": [
        "pumping",
        "offbeat_bassline",
        "rolling_toms",
        "136-142 bpm"
    ]
}

WAVEFORM_TIMBRES = {
    "sine": "deep_sub_thud",
    "triangle": "soft_rounded_tick",
    "square": "hollow_retro_snap",
    "sawtooth": "bright_biting_crack",
    "pulse": "clicky_nasal_pop",
    "noise": "hissing_metallic_wash"
}


def parse_sequence(sequence):
    if not sequence:
        raise ValueError("step sequencer data must contain at least one hit")
    grid, waveforms = {}, {}
    for hit in sequence:
        instrument = hit["instrument"]
        grid.setdefault(instrument, set()).add(int(hit["step"]))
        waveforms[instrument] = hit.get("waveform", "sine")
    return grid, waveforms


def analyze(grid):
    span = max(max(steps) for steps in grid.values()) + 1
    bars = max(1, -(-span // 16))
    kicks = sorted(grid.get("kick", set()))
    hats = grid.get("hat", set())
    snares = grid.get("snare", set())
    return {
        "steps": bars * 16,
        "kick_regular": len(kicks) >= 4 and all(step % 4 == 0 for step in kicks),
        "kick_offbeat": any(step % 4 != 0 for step in kicks),
        "hat_density": len(hats) / (bars * 16),
        "snare_halftime": bool(snares) and all(step % 16 == 8 for step in snares)
    }


def classify(features):
    if features["kick_regular"] and features["hat_density"] >= 0.5:
        return "techno", "driving"
    if features["kick_regular"]:
        return "house", "steady"
    if features["kick_offbeat"] and features["steps"] >= 32:
        return "drum_and_bass", "rolling"
    if features["kick_offbeat"]:
        return "breakbeat", "shuffled"
    if features["snare_halftime"]:
        return "dubstep", "halftime"
    return "trance", "pumping"


def describe_timbres(waveforms):
    return {
        instrument: WAVEFORM_TIMBRES[wave]
        for instrument, wave in waveforms.items()
        if wave in WAVEFORM_TIMBRES
    }


def format_report(name, genre, tempo, timbres):
    voices = ", ".join(f"{part}={timbre}" for part, timbre in sorted(timbres.items()))
    return f"{name}: {genre} [{tempo}] :: {voices}"


def program(sequence):
    grid = parse_sequence(sequence)[0]
    genre, feel = classify(analyze(grid))
    tempo = f"{feel} {GENRE_SIGNATURES[genre][-1]}"
    return (genre, tempo)


def main():
    four_on_the_floor = [
        {"instrument": "kick", "step": 0, "waveform": "sine"},
        {"instrument": "kick", "step": 4, "waveform": "sine"},
        {"instrument": "kick", "step": 8, "waveform": "sine"},
