        ("four_on_the_floor", four_on_the_floor),
        ("chopped_break", chopped_break),
        ("halftime_grid", halftime_grid)
    ):
        genre, tempo = program(pattern)
        timbres = describe_timbres(parse_sequence(pattern)[1])
        print(format_report(name, genre, tempo, timbres))


