        "restricted": [
            "red meats",
            "processed snacks",
            "butter",
        ],
        "carb_limit": 250,
    },
}


def normalize(name):
    return name.strip().lower().replace(" diet", "")


def evaluate(food):
    key = normalize(food)
    for regimen, profile in DIETS.items():
        if key in profile["allowed"]:
            return regimen, profile["carb_limit"]
    raise ValueError("unknown allowed food: {!r}".format(food))


def restricted_foods(regimen):
    key = normalize(regimen)
    if key not in DIETS:
        raise ValueError("unknown regimen: {!r}".format(regimen))
    return list(DIETS[key]["restricted"])


def describe(food):
    regimen, limit = evaluate(food)
    return "{} -> {} diet (carb limit {} g/day), avoid: {}".format(
        food,
        regimen,
        limit,
        ", ".join(restricted_foods(regimen)),
    )


