def flatten_dict(nested_dict, separator):
    flattened = {}
    for key, value in nested_dict.items():
        if isinstance(value, dict):
            for sub_key, sub_value in value.items():
                flattened[f"{key}{separator}{sub_key}"] = sub_value
        else:
            flattened[key] = value
    return flattened

def another_flatten_example():
    test_dict_1 = {
        'alpha': 1,
        'beta': {
            'gamma': 2,
            'delta': 3,
        },
        'epsilon': 4,
    }
    sep_1 = '_'

    result_1 = flatten_dict(
        test_dict_1,
        sep_1,
    )
    print(result_1)

    test_dict_2 = {
        'outer': {
            'inner_1': 100,
            'inner_2': 200,
        },
    }
    sep_2 = '.'

    result_2 = flatten_dict(
        test_dict_2,
        sep_2,
    )
    print(result_2)

    assert flatten_dict(
        {'a': 1, 'b': {'c': 2, 'd': 3}},
        '_',
    ) == {'a': 1, 'b_c': 2, 'b_d': 3}

    assert flatten_dict(
        {'x': {'y': 10}},
        '.',
    ) == {'x.y': 10}

    assert flatten_dict(
        {
            'key1': 'value1',
            'key2': {
                'sub_key1': 'sub_value1',
                'sub_key2': 'sub_value2',
            },
            'key3': 123,
        },
        '-',
    ) == {
        'key1': 'value1',
        'key2-sub_key1': 'sub_value1',
        'key2-sub_key2': 'sub_value2',
        'key3': 123,
    }

