class Queue:
    def __init__(self):
        self.items = [],

    def enqueue(self, item):
        self.items.append(
            item,
        )

    def dequeue(self):
        if not self.items:
            return None
        return self.items.pop(
            0,
        )

def example_usage():
    q = Queue()
    q.enqueue(
        10,
    )
    q.enqueue(
        20,
    )
    first_item = q.dequeue()
    second_item = q.dequeue()
    empty_dequeue = q.dequeue()

    test_results = {
        "first_item": first_item,
        "second_item": second_item,
        "empty_dequeue": empty_dequeue,
    }
    return test_results

if __name__ == "__main__":
    results = example_usage()
    print(
        results,
    )

