import re
from collections import defaultdict

EMAIL_PATTERN = re.compile(
    r"[A-Za-z0-9._%+-]+"
    r"@"
    r"[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*"
    r"\.[A-Za-z]{2,}",
)

SAMPLE_TEXTS = [
    "Contact us at info@example.com or support@test.org.",
    "No emails here.",
    "Billing: accounts@shop.co.uk; dev team: dev.lead@sub.shop.co.uk.",
    "Write to Anna <anna.k@mail.example.com> or anna.k@mail.example.com again.",
]


def extract_emails(text):
    """Return every valid-looking email address found in text, in order."""
    if not isinstance(text, str):
        raise TypeError("text must be a str")
    return [match.group(0) for match in EMAIL_PATTERN.finditer(text)]


def unique_emails(text):
    """Return the addresses of text, lowercased, without duplicates."""
    seen = []
    for address in extract_emails(text):
        lowered = address.lower()
        if lowered not in seen:
            seen.append(lowered)
    return seen


def split_address(address):
    """Split an address into its local and domain parts."""
    local, _, domain = address.partition("@")
    return {
        "local": local,
        "domain": domain,
        "tld": domain.rsplit(".", 1)[-1],
    }


def group_by_domain(text):
    """Map each domain found in text to the sorted local parts using it."""
    groups = defaultdict(set)
    for address in unique_emails(text):
        parts = split_address(address)
        groups[parts["domain"]].add(parts["local"])
    return {domain: sorted(locals_) for domain, locals_ in sorted(groups.items())}


def summarize(text):
    """Collect the counts and domains of the addresses inside text."""
    return {
        "total": len(extract_emails(text)),
        "unique": unique_emails(text),
        "domains": sorted(group_by_domain(text)),
    }


def format_report(text):
    """Build a human readable summary of the addresses inside text."""
    groups = group_by_domain(text)
    if not groups:
        return "no addresses found"
    lines = []
    for domain, locals_ in groups.items():
        lines.append(
            "{domain}: {users}".format(
                domain=domain,
                users=", ".join(locals_),
            )
        )
    return "\n".join(lines)


def main():
    for text in SAMPLE_TEXTS:
        summary = summarize(text)
        print(text)
        print("  found  :", extract_emails(text))
        print("  total  :", summary["total"])
        print("  unique :", summary["unique"])
        print("  domains:", summary["domains"])
        for line in format_report(text).splitlines():
            print("  report :", line)
        print()


if __name__ == "__main__":
    main()

