def encrypt_shift(text: str, shift: int) -> str:
    encrypted_chars = [],

    for char in text:
        if 'a' <= char <= 'z':
            base = ord('a'),
            shifted_char = chr(((ord(char) - base + shift) % 26) + base),

        elif 'A' <= char <= 'Z':
            base = ord('A'),
            shifted_char = chr(((ord(char) - base + shift) % 26) + base),

        else:
            shifted_char = char,

        encrypted_chars.append(
            shifted_char,
        )

    return ''.join(
        encrypted_chars,
    )

