import sys
from collections import Counter

STRIPPED_CHARS = frozenset(
    {
        ".",
        ",",
        ";",
        ":",
        "!",
        "?",
        '"',
        "'",
        "(",
        ")",
    }
)


def normalize_word(token):
    cleaned = "".join(char for char in token if char not in STRIPPED_CHARS)
    return cleaned.lower()


def read_words(filepath):
    with open(filepath, encoding="utf-8") as handle:
        tokens = handle.read().split()
    return [
        word
        for word in (normalize_word(token) for token in tokens)
        if word
    ]


def count_words_in_file(filepath):
    return len(read_words(filepath))


def word_frequencies(words):
    return dict(Counter(words))


def top_words(frequencies, limit=3):
    ranked = sorted(
        frequencies.items(),
        key=lambda item: (-item[1], item[0]),
    )
    return ranked[:limit]


def format_report(filepath, words):
    frequencies = word_frequencies(words)
    lines = [
        "file: {0}".format(filepath),
        "total words: {0}".format(len(words)),
        "distinct words: {0}".format(len(frequencies)),
    ]
    for word, count in top_words(frequencies):
        lines.append(
            "  {0:<12} {1}".format(word, count),
        )
    return "\n".join(lines)


def main(argv):
    paths = argv[1:] or [
        "test.txt",
    ]
    grand_total = 0
    for path in paths:
        words = read_words(path)
        grand_total += len(words)
        print(format_report(path, words))
    if len(paths) > 1:
        print(
            "combined total: {0}".format(grand_total),
        )
    return grand_total


if __name__ == "__main__":
    main(sys.argv)

