    """Convert a binary string such as '1011' into the integer 11."""
    cleaned = validate_binary_string(binary_string)
    total = 0
    for char in cleaned:
        total = total * 2 + BINARY_DIGITS[char]
    return total


def place_values(binary_string):
    """List the (bit, exponent, contribution) triples of the set bits."""
    cleaned = validate_binary_string(binary_string)
    width = len(cleaned)
    return [
        (
            char,
            width - 1 - index,
            1 << (width - 1 - index)
        )
        for index, char in enumerate(cleaned)
        if BINARY_DIGITS[char]
    ]


def expansion(binary_string):
    """Render the sum-of-powers expansion, e.g. '2^2 + 2^0 = 5'."""
    terms = ["2^%d" % exponent for _bit, exponent, _value in place_values(binary_string)]
    if not terms:
        return "0 = 0"
    return "%s = %d" % (' + '.join(terms), binary_to_decimal(binary_string))


def format_row(sample, decimal, width):
    """Format one aligned table row for a successfully converted sample."""
    return "%-*s | %7d | %s" % (
        width,
        sample,
        decimal,
        expansion(sample)
    )


def report(samples):
    """Build the table header plus one line per sample, failures included."""
    width = max(len(COLUMN_HEADERS[0]), *(len(str(sample)) for sample in samples))
    lines = [
        "%-*s | %7s | %s" % ((width,) + COLUMN_HEADERS)
    ]
    for sample in samples:
        try:
            decimal = binary_to_decimal(sample)
        except (TypeError, ValueError) as error:
            lines.append("%-*s | %7s | %s" % (width, sample, 'error', error))
        else:
            lines.append(format_row(sample, decimal, width))
    return lines


def main():
    samples = [
        '101',
        '1111',
        '1011',
        '0',
        '1000_0001',
        ' 110 ',
        '12',
        ''
    ]
    for line in report(samples):
        print(line)


if __name__ == '__main__':
    main()

