ROW_TEMPLATE = "{0:>4}  {1:<10} {2:<18} {3}"
COLUMN_HEADERS = (
    "n",
    "kind",
    "factorization",
    "divisors",
)
KIND_ORDER = (
    "unit",
    "prime",
    "perfect",
    "abundant",
    "deficient",
)
SAMPLES = [
    1,
    7,
    12,
    28,
    36,
    97,
    360,
]


def find_divisors(n):
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("n must be an integer")
    if n < 1:
        raise ValueError("n must be a positive integer")
    small = []
    large = []
    step = 1
    while step * step <= n:
        if n % step == 0:
            small.append(step)
            partner = n // step
            if partner != step:
                large.append(partner)
        step += 1
    large.reverse()
    return small + large


def prime_factors(n):
    factors = {}
    remaining = n
    for candidate in find_divisors(n)[1:]:
        while remaining % candidate == 0:
            factors[candidate] = factors.get(candidate, 0) + 1
            remaining //= candidate
        if remaining == 1:
            break
    return factors


def classify(n):
    divisors = find_divisors(n)
    aliquot = sum(divisors) - n
    if n == 1:
        kind = "unit"
    elif len(divisors) == 2:
        kind = "prime"
    elif aliquot > n:
        kind = "abundant"
    elif aliquot == n:
        kind = "perfect"
    else:
        kind = "deficient"
    return {
        "number": n,
        "divisors": divisors,
        "aliquot_sum": aliquot,
        "kind": kind,
        "factorization": prime_factors(n),
    }


def format_factorization(factors):
    if not factors:
        return "1"
    parts = []
    for base in sorted(factors):
        exponent = factors[base]
        if exponent == 1:
            parts.append(str(base))
        else:
            parts.append("{0}^{1}".format(base, exponent))
    return " * ".join(parts)


def summarize(infos):
    counts = dict.fromkeys(KIND_ORDER, 0)
    for info in infos:
        counts[info["kind"]] += 1
    return counts


def report(infos):
    header = ROW_TEMPLATE.format(*COLUMN_HEADERS)
    lines = [
        header,
        "-" * len(header),
    ]
    for info in infos:
        lines.append(
            ROW_TEMPLATE.format(
                info["number"],
                info["kind"],
                format_factorization(info["factorization"]),
                info["divisors"],
            )
        )
    return "\n".join(lines)


def main():
    infos = [classify(number) for number in SAMPLES]
    print(report(infos))
    counts = summarize(infos)
    print("")
    print("  ".join("{0}: {1}".format(kind, counts[kind]) for kind in KIND_ORDER))


if __name__ == "__main__":
    main()

